export default [{"id":71,"question":"وهذه سائلة تقول: هل يجوز تغطية اليدين في الصلاة أم لا، لأننا سمعنا في هذه الأيام أنه لا يجوز أن تصلي المرأة ويديها كاشفة، بل لا بد من تغطية اليدين بالرغم من قول الرسول ﷺ المرأة كلها عورة في الصلاة ما عدا وجهها وكفيها؟","title":"حكم تغطية المرأة كفيها وقدميها أثناء الصلاة","answer":"الجواب: الكفان سترهما أفضل، ولا يجب سترهما، والوجه كشفه أفضل، السُّنة كشف الوجه إذا ما كان عندها أجنبي تكشف وجهها ويديها لا بأس، وإن غطت الكفين هذا أفضل وإلا فلا حرج. أما القدمان فيجب سترهما وجميع البدن، إلا إذا كان عندها أجنبي تستر بدنها كله حتى الوجه، إذا كان عندها أجنبي كأخي زوجها أو غيره.","link":"https://binbaz.org.sa/fatwas/2989/حكم-تغطية-المراة-كفيها-وقدميها-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0048.mp3","categories":["ستر العورة للمصلي"]},{"id":73,"question":"تقول أيضاً: ما هي عورة المرأة للمرأة؟","title":"ما حدود عورة المرأة أمام المرأة؟","answer":"الجواب: ما بين السرة والركبة، هذه العورة بالنسبة إلى المرأة مع المرأة، والرجل مع الرجل، فإذا رأت المرأة من المرأة ما فوق السرة كالثدي، والصدر، والحلق، والشعر؛ لا بأس، والساق، لكن الحشمة كونها تتستر ستراً كاملاً يكون هذا أفضل وأحشم حتى لا يتساهل الناس بهذا الأمر، فيجرّئهم على الكشف عند الأجنبي، فالتستر الكامل والحشمة يكون أفضل وأحسن بين النساء، لكن إذا رأت المرأة من أختها في الله الصدر أو الثدي عند الرضاع، أو رأت شعرها، أو رأت الساق؛ لا حرج؛ لكن كونها تلبس لباسًا كاملا محتشمًا حتى يُقتدى بها، وحتى لا تتعرض لرؤية سائق، أو خادم، أو أجنبي عارض؛ هذا أوْلى وأحوط.","link":"https://binbaz.org.sa/fatwas/2991/ما-حدود-عورة-المراة-امام-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0050.mp3","categories":["ستر العورة للمصلي"]},{"id":156,"question":"في هذا العصر انتشر لباسُ الغرب، ومنها البنطلون، ومن صفته أنه ضيقٌ، فما حكم لبس هذا البنطلون أولًا؟ ثم ما حكم الصلاة فيه، مع أنه يفصل العورة بوضوحٍ أثناء السجود؟ وما الحل؟","title":"حكم لبس البنطلون والصلاة فيه","answer":"الجواب: أما لبس البنطلون فقد شاع بين الناس، ولم يبقَ خاصًّا بالكفار، شاع بين المسلمين وانتشر بينهم، وصار في جنودهم، فلم يكن الآن خاصًّا بالكفار، بل انتشر بين المسلمين وغيرهم، مثل: لبس الكنادر، وركوب السيارات، وركوب الطائرات، فهذا عمَّ الناس كلهم، ولم يبقَ خاصًّا بالكفار.\nلكن يجب أن يكون واسعًا لا ضيقًا، وأن يتحرز من هذا الشيء الذي يفصل العورة ويُبَيِّن حجمها ويُؤذيه في صلاته، فينبغي على المسؤولين أن يضعوا شيئًا واسعًا جيدًا يستر العورة ولا يُبين حجمها، ويُعينه على صلاته ووضوئه وغير ذلك، أما هذا الضَّيق الذي يُؤذيه ويُبرز عورته فلا ينبغي لبسه، والذي يظهر أنه لا يجوز، وعليه أن يُعالج هذه الأمور مع المسؤولين حتى يُغيّروا هذه الملابس الضَّارة الضيقة.\nولعلنا إن شاء الله نفعل ما نستطيع في هذا -إن ذُكّرنا بذلك- ونمنعه الآن إن شاء الله، ونرجو من الله أن يُعيننا على ذلك، فإنَّ تذكير المسؤولين مهمٌّ بهذا، وهم من كل خيرٍ قريبون -نسأل الله لنا ولهم الهداية.","link":"https://binbaz.org.sa/fatwas/3693/حكم-لبس-البنطلون-والصلاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0149.mp3","categories":["اللباس والزينة","ستر العورة للمصلي"]},{"id":641,"question":"الصلاة مضطبعًا؟","title":"ما حكم صلاة المضطبع؟","answer":"الجواب: يصح؛ لأن أحد العاتقين مستور، لكن أن يستر العاتقين أوْلى.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6577/ما-حكم-صلاة-المضطبع","audio":"https://files.zadapps.info/binbaz.org.sa/maram209 - 03 - .mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":645,"question":"س: إن صلى مكشوف العاتقين؟","title":"حكم صلاة من عاتقاه مكشوفان","answer":"الجواب: فيه نظر، ينبغي له أن يعيد؛ لقوله ﷺ: لا يصلي أحدكم في ثوب واحد ليس على عاتقه منه شيء وفي اللفظ الآخر: ليس على عاتقيه منه شيء متفق على صحته، فينبغي له أن يستر عاتقيه أو أحدهما على الأقل إذا قدر. أما إذا كان ما عنده شيء فاتقوا الله ما استطعتم.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6675/حكم-صلاة-من-عاتقاه-مكشوفان","audio":"https://files.zadapps.info/binbaz.org.sa/maram213 - 03 - .mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":1298,"question":"سائلة تقول: هل يجوز كشف القدم في الصلاة؟","title":"هل يجوز للمرأة كشف القدم في الصلاة؟","answer":"الجواب:\nأكثر أهل العلم على أنها تسترها في الصلاة، المرأة تستر قدمها في الصلاة، وفي حديثٍ عن أمِّ سلمة أنها سُئلت عن هذا: تُصلي المرأةُ في درعٍ وخمارٍ، فقالت رضي الله عنها: \"إذا كان الدرعُ سابغًا يُغطي ظهور قدميها\"، جاء مرفوعًا عنها، وموقوفًا، والموقوف عند أهل العلم أصحّ، فالمشروع لها أن تُغطي قدميها بالثياب الساترة، أو جوارب، هذا هو الأحوط لها، وهو الذي ينبغي لها، وهو واجبٌ عند جمهور أهل العلم.\nأما الكفَّان: فأمرهما أوسع، إن غطّتهما فهو أحسن، وإن كشفتهما في الصلاة مع الوجه فلا بأس.\nأما الوجه: فالسُّنة كشفه للمرأة في الصلاة، إلا أن يكون عندها أجنبي فتستره، أما إذا كان ما عندها إلا محارمها، أو نساء، أو ما عندها أحدٌ؛ فالسنة كشف الوجه.  أما اليدان –الكفَّان- فسترهما أفضل، وإن كشفتهما صحَّت الصلاةُ على الصحيح، وأما القدمان فالواجب سترهما، هذا هو الذي عليه أكثر أهل العلم.","link":"https://binbaz.org.sa/fatwas/21371/هل-يجوز-للمراة-كشف-القدم-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1114سائلة تقول هل يجوز كشف القدم في الصلاة؟ ابن باز فتاوى.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":1813,"question":"الرُّكْبَة هل تدخل في العورة؟","title":"ما حدود العورة؟ وهل الرُّكْبَة منها؟","answer":"الجواب:\nلا، الرُّكْبَة وما تحتها ليس من العورة، فالنبي ﷺ جلس ذات يومٍ في بئرٍ وأبدى ركبتيه، وهكذا جلس معه أبو بكر وعمر وعثمان.\nس: وما فوق الركبة؟\nج: ما فوق الركبة عورة، والركبة وما تحتها ليس بعورةٍ.\nس: تقسيم بعض أهل العلم العورة إلى: مُخَفَّفة ومُغَلَّظة؟\nج: المُغَلَّظة الفَرْج: الدبر والقبل، هذه مُغَلَّظة، وما دونها غير مُغَلَّظة إلى الركبة.\nس: لكن الحكم في السّتر واحد؟\nج: نعم، يجب سترها.","link":"https://binbaz.org.sa/fatwas/21921/ما-حدود-العورة-وهل-الركبة-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العورة وحدودها.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":2328,"question":"ما الدليل على ستر يدي المرأة وقدميها في الصلاة؟","title":"ما دليل ستر يدي المرأة وقدميها بالصلاة؟","answer":"الجواب:\nليس هناك إلا حديث: المرأة عورة، إطلاق الحديث، وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53]، وأقرب ما احتُجَّ به في هذا هو إطلاق: المرأة عورة، والصواب كشف الوجه فقط، أمَّا اليدان فإن كشفتهما فلا بأس، وإن سترتهما فهو أفضل، وحديث أم سلمة في غطاء القدمين.","link":"https://binbaz.org.sa/fatwas/22452/ما-دليل-ستر-يدي-المراة-وقدميها-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ستر يدي المرأة وقدميها في الصلاة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":2330,"question":"مَن قال أن ستر أحد العاتقين في الصلاة سنة وليس بواجبٍ؟","title":"حكم ستر العاتقين في الصلاة","answer":"الجواب:\nما هو بواجبٍ؛ لقول النبي ﷺ: ليس على عاتقه، وفي بعض الروايات: عاتقيه، فإذا ستر أحد العاتقين حصل المطلوبُ، لكن سترهما أفضل وأحوط.","link":"https://binbaz.org.sa/fatwas/22454/حكم-ستر-العاتقين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ستر العاتقين في الصلاة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":2456,"question":"صلاة الرجل حاسِرَ الرأس؟","title":"ما حكم صلاة الرجل حاسِرَ الرأس؟","answer":"الجواب:\nلا حرج، المحرم بالحج والعمرة يصلي حاسِرَ الرأس مدة الإحرام، ما عليه إلا إزاره ورداؤه، إلا إذا لبس زينته يكون أكمل.","link":"https://binbaz.org.sa/fatwas/22585/ما-حكم-صلاة-الرجل-حاسر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة الرجل حاسر الرأس.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":2611,"question":"إنسان عنده سروال ويصلي فيه، وفيه في مكان العورة مثل حبة الذرة مشقوق، وصلى به صلوات عديدة، ويسأل عن صلاته؟","title":"حكم صلاة مَن في ملابسه شِقٌّ يسير","answer":"الجواب: ولا عليه شيء غيره؟\nس: لا ليس عليه شيء؟\nالشيخ: وما درى عنه؟\nس: يظن أنه جائز الشيء اليسير جدًّا؟\nالشيخ: يلاحظه في المستقبل، يتفقّده، واللي مضى يعفو الله عنه، لكن يتفقده في المستقبل حتى يكون مستورًا من جميعه، ولو قليل.","link":"https://binbaz.org.sa/fatwas/22746/حكم-صلاة-من-في-ملابسه-شق-يسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من صلى وفي ملابسه شق.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":3415,"question":"بعض الفانيلات الداخلية تقريبًا عرضها 2 سم على العاتق، هل تجوز الصلاة فيها؟","title":"ما مقدار سَتْر العاتق المُجْزئ في الصلاة؟","answer":"الجواب: تقوم مقام الرداء.\nس: مَنْ صلى ولم يَسْتَر عاتقيه هل صلاته صحيحة؟\nالشيخ: النبي ﷺ قال: لا يصل أحدكم في الثوب الواحد ليس على عاتقه منه شيء، والقول الصواب أن مع القدرة ما يجوز، والجمهور يرون الجواز إذا ستر العورة كفى؛ لأن ستر العاتقين مستحب. لكن الصواب لا بدّ من سترهما؛ لأن الرسول ﷺ أمر بذلك.\nس: الثوب إن كان واسعًا؟\nالشيخ: وإن كان ضيقًا فاتّزر به، هذا عند العجز.\nس: لكن إذا كان قادرًا -أحسن الله إليك- ولم يجعل شيئًا على عاتقه؟\nالشيخ: لا بد من جعل شيء على العاتقين أو أحدهما إذا كان قادرًا.\nس: يُعيد الصلاة؟\nالشيخ: نعم.\nس: حديث جابر من صلى بثوب واحد؟\nالشيخ: لا بأس به إذا كان عاجزًا، أو كان الثوب الواحد أطرافه على عاتقيه، أو طرفه على عاتقه.\nس: لو جعل على عاتقه، واحد فقط، على العاتق؛ يزول النهي؟\nالشيخ: نعم ليس على عاتقه منه شيء، إذا كان طرفه على عاتقه أجزأ، لكن كونه على عاتقيه أكمل.","link":"https://binbaz.org.sa/fatwas/23587/ما-مقدار-ستر-العاتق-المجزى-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل من حديث لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء..mp3","categories":["ستر العورة للمصلي"]},{"id":3539,"question":"قول العلامة ابن القيم: إن العورة عورتان، عورة مغلّظة، وعورة مخفّفة، الفخذان عورة مخفّفة؟","title":"حكم ستر الفخذينللكبير والصغير","answer":"الجواب: لا شك أن العورة \"القُبُل والدُّبُر\" عورة مغلّظة، ولكن الفخذ حِماها، الفخذ حِمَىً للعورة المغلظة.\nوالصواب أنها عورة، والأحاديث الثلاثة يشدّ بعضها بعضًا حديث محمد بن جحش، وجرهد، وابن عباس، يشدّ بعضها بعضًا فتكون ناسخة لما وقع منه ﷺ.\nس: الذي يلبس سروالًا قصيرًا، عليه ثوب شفاف؟\nالشيخ: ما يجوز هذا، لا بدّ من ستر الفخذين.\nس: الصبي يستر الفخذ؟\nالشيخ: إذا بلغ الحُلُم، لكن سترها إذا كان ابن  عشرة أو نحوها أحوط وأحسن، وأبعد عن الفتنة.","link":"https://binbaz.org.sa/fatwas/23721/حكم-ستر-الفخذين-للكبير-والصغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العورة عورتان مغلظة، ومخففة فهل الفخذ عورة مخففة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":3542,"question":"رجل في الصحراء، وليس معه ماء، وعلى ثوبه نجاسة، فماذا يعمل بالنسبة للصلاة؟","title":"كيف يصلي من كان بالصحراء وفي ثوبه نجاسة؟","answer":"الجواب: يصلي في ثوبه؛ يتيمم ويصلي في ثوبه، ولا يصلي عريانًا، معذور.","link":"https://binbaz.org.sa/fatwas/23724/كيف-يصلي-من-كان-بالصحراء-وفي-ثوبه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة من كان في الصحراء، وليس معه ماء، وعلى ثوبه نجاسة.mp3","categories":["ستر العورة للمصلي"]},{"id":4041,"question":"كشف الفخذ من العورة؟","title":"هل الفخذ من العورة؟","answer":"الجواب: نعم، الفخذ من العورة.","link":"https://binbaz.org.sa/fatwas/24277/هل-الفخذ-من-العورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الفخذ من العورة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":4513,"question":"الفانلة العلاقية...؟","title":"هل الفانلة العلاقية تستر العاتق في الصلاة؟","answer":"الجواب: إذا كانت تستر المنكبين، أو أحد المنكبين. أما الخيط ما أظن أنه يكفي، ما أعتقد أنه يكفي؛ لأنه ليس بساترٍ.","link":"https://binbaz.org.sa/fatwas/24793/هل-الفانلة-العلاقية-تستر-العاتق-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لا يصل أحدُكم في الثوب الواحد ليس على عاتقه منه شيء، الصلاة بالفانلة العلاقية.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":4514,"question":"يُستحب أن يُعيد إذا صلَّى وعاتقاه مكشوفان مع القُدرة؟","title":"ما حكم من صلى وعاتقاه مكشوفان؟","answer":"الجواب: إذا قلنا بالوجوب وجب أن يُعيد إذا تعمَّد، أما إذا كان جاهلًا قد يُعفى عنه، لكن إذا قلنا بالوجوب -كما هو مذهب أحمد وجماعة- وجوب ستر العاتقين أو أحدهما لحديث أبي هريرة.\nس: ما يأثم...؟\nج: يأثم... إذا قلنا بالوجوب، وهو الأظهر، وهو الأحوط؛ لأن الأصل في الأوامر الوجوب، والأصل في النهي التحريم، هذا هو الأصل؛ ولأن الناس عند سماع الاستحباب وعند اعتقاد الاستحباب يغلب عليهم التَّساهل، وهذه أوامر ونواهٍ ما ينبغي فيها التَّساهل.\nس: الكتف ليس من العورة... عورته مستورة، والكتف ليس منها؟\nج: لكن الرسول ﷺ أمر بسترها عند القُدرة قال: فإن كان واسعًا فالتحف به، وخالف بين طرفيه، و لا يُصلِّ أحدُكم بالثوب الواحد ليس على عاتقه منه شيء –أو: عاتقيه كما في \"الصحيحين\"، فينبغي الجمع بين هذا وهذا.\nس: مَن قال: يأثم ولا يُعيد؛ لأنها ليست عورةً؟\nج: الأقرب -والله أعلم- أنه إذا تعمَّد وتساهل أنه يُعيد، أما إن كان عن جهلٍ وخرج الوقت فالأمر أوسع.","link":"https://binbaz.org.sa/fatwas/24794/ما-حكم-من-صلى-وعاتقاه-مكشوفان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعيد الصلاة من صلى وعاتقاه مكشوفان.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":4515,"question":"مَن رأى عورته وقت الصلاة هل تبطل صلاته؟","title":"هل تبطل صلاة من رأى عورته وقت الصلاة؟","answer":"الجواب: لا، ما تبطل، لكن ينبغي له أن يعتني بها، يعتني بزر الثوب، أو تصغير الجيب، أو لفّ شيء عليه حتى لا يرى عورته، أو تكون عليه سراويل أو إزار تحت الثوب، يعني ما يُسمَّى: مكشوف العورة.","link":"https://binbaz.org.sa/fatwas/24795/هل-تبطل-صلاة-من-راى-عورته-وقت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تبطل صلاة من رأى عورته وقت الصلاة.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":5118,"question":"وهذه سائلة تقول: هل يجوز تغطية اليدين في الصلاة أم لا، لأننا سمعنا في هذه الأيام أنه لا يجوز أن تصلي المرأة ويديها كاشفة، بل لا بد من تغطية اليدين بالرغم من قول الرسول ﷺ المرأة كلها عورة في الصلاة ما عدا وجهها وكفيها، أفيدوني جزاكم الله خيرًا؟","title":"حكم تغطية المرأة يديها ووجهها في الصلاة","answer":"الجواب: الكفان سترهما أفضل، ولا يجب سترهما، والوجه كشفه أفضل، السنة كشف الوجه إذا ما كان عندها أجنبي تكشف وجهها ويديها، لا بأس، وإن غطت الكفين هذا أفضل وإلا فلا حرج، أما القدمان فيجب سترهما وجميع البدن، إلا إذا كان عندها أجنبي تستر بدنها كله حتى الوجه، إذا كان عندها أجنبي كأخي زوجها أو غيره.","link":"https://binbaz.org.sa/fatwas/30026/حكم-تغطية-المراة-يديها-ووجهها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 48.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":5331,"question":"ما هو قولكم في ستر العاتق هل هو واجب؟ وهل العاتق من العورة؟ وإن كان من العورة فمن أي أنواعها؟ وهل يجوز كشفها؟","title":"ما حكم ستر العاتق؟ وهل هو من العورة؟","answer":"الجواب: جاء في الحديث الصحيح يقول ﷺ: لا يصلي أحدكم في الثوب وليس على عاتقه منه شيء فالعاتق ليس بعورة، لكن أمر النبي بستره إذا تيسر ذلك، وقال لجابر: إن كان الثوب واسعًا فالتحف به، وإن كان ضيقًا فاتّزر به، فإذا كان عنده رداء وضعه على كتفيه أو قميص، فستر العاتقين أو أحدهما واجب في الصلاة، وإن كان ليس بعورة في غير الصلاة؛ لقوله ﷺ: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء متفق عليه.[1]","link":"https://binbaz.org.sa/fatwas/31001/ما-حكم-ستر-العاتق-وهل-هو-من-العورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 052.mp3","categories":["ستر العورة للمصلي","اللباس والزينة"]},{"id":6033,"question":"هل تصح صلاة المرأة بالملابس الضيقة مع خروج شيء من شعر رأسها، وكذلك الحلي، واليدين إذا كانت ليست بحضرة الرجال الأجانب؟ وهل الأحسن أن تلبس المرأة العباءة في الصلاة؟","title":"حكم صلاة المرأة مكشوفة الشعر واليدين والقدمين","answer":"الجواب: المرأة عليها التستر في الصلاة، يجب عليها أن تستر نفسها في الصلاة، ما عدا الوجه يكون عليها جلباب، أو ثياب ساترة تستر بدنها كله، والشعر يجب أن يستر، ولو في بيتها، ولو ما عندها  أحد، يجب عليها أن تتستر. النبي ﷺ قال: لا يقبل الله صلاة حائض إلا بخمار الحائض يعني البالغة، لا تقبل صلاتها إلا بخمار، يعني ساتر، فلا بدّ من ستر شعرها كله، وبدنها كله في الصلاة، حتى أقدامها تسترها، إما بالجوارب، أو بالثوب الساتر المرتخي الذي يستر قدميها. أما الكفان فإن سترت الكفين؛ فهو أحوط، وإن كشفتهما؛ أجزأت الصلاة، لكن ستر الكفين أفضل، وأحوط، ولا يبقى إلا الوجه، وجهها تكشفه في الصلاة إذا كان ما عندها أجنبي، ما عندها إلا النساء، أو زوجها تصلي مكشوفة الوجه، لكن الشعر، وجميع البدن يستر، والقدمين ما عدا الكفين، فأمرهما أوسع، إن سترتهما؛ فحسن، وإن كشفتهما مع الوجه؛ فالأمر فيه واسع.","link":"https://binbaz.org.sa/fatwas/1429/حكم-صلاة-المراة-مكشوفة-الشعر-واليدين-والقدمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_368.mp3","categories":["ستر العورة للمصلي","قضايا المرأة"]},{"id":6056,"question":"كثير من النساء يصلين وأرجلهن مكشوفة، وبعض الناس يقولون لهن هذا ما فيه شيء؟","title":"حكم صلاة المرأة كاشفة لرجليها","answer":"الجواب: على كل حال يجب أن يعلم أن ستر الرجلين عند جمهور أهل العلم واجب؛ لأنها عورة، وذهب بعض أهل العلم كأبي حنيفة، وجماعة يقولون: بأن الرجلين ليستا من العورة، ولهذا بعض الناس يأخذ بهذا.  لكن الصواب: أنها عورة، إنما الوجه فقط، والكفين على الأرجح في الصلاة ليسا بعورة، وأما بدنها، رأسها، وجميع بدنها، حتى الرجلين كلها عورة في الصلاة، لكن هذا عن جمهور أهل العلم، بعض أهل العلم يرى أن الرجلين ليستا بعورة، كأبي حنيفة، وجماعة، ولكن ينبغي للمرأة أن تسترهما أيضًا. السؤال:  سمعنا أنه سيكون ما يمنح تصريح بالدعوة إلا من يحمل شهادة جامعية؟ الجواب: نعم جامعية، أو درس على العلماء، يزكيه العلماء، ولو ما معه شهادة جامعية، إذا كان زكاه العلماء، وأنه يعرف يتكلم، ويحسن الكلام، ويوثق به إذا سئل، وأفتى؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/1467/حكم-صلاة-المراة-كاشفة-لرجليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_397.mp3","categories":["ستر العورة للمصلي","قضايا المرأة"]},{"id":6618,"question":"الصلاة تجوز بالثوب الخفيف إذا كان هناك ليس عليه إزار طويل، ولا سروال؟","title":"حكم الصلاة في الثوب الشفاف وليس تحته سروال","answer":"الجواب: لا يجوز، لا يجوز، لا بد من السترة التي تستر ما بين السرة، والركبة، إما سراويل ثخين ساتر، وإما قميص ساتر، وأما بعض الناس الذي يفعل سراويل رقيقة تبدو فيها أفخاذه، هذا لا يجوز، الذي عليه عامة أهل العلم، وجمهور أهل العلم أن هذا لا يجوز،  بل لا بد من سترة كافية بين السرة، والركبة، وإذا كان القميص ساترا لذلك؛ كفى عن السراويل.","link":"https://binbaz.org.sa/fatwas/2452/حكم-الصلاة-في-الثوب-الشفاف-وليس-تحته-سروال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_979.mp3","categories":["ستر العورة للمصلي","قضايا المرأة"]},{"id":6958,"question":"نعلم أنه يجب ستر العورة في الصلاة، ولكننا نجد كثيرًا من الناس يلبس ملابس خفيفة تظهر عوراتهم، وبهذا تبطل الصلاة، فنطلب من سماحتكم توضيح ذلك للناس، وجزاكم الله خيرًا.","title":"حكم الصلاة بثياب خفيفة لا تستر العورة","answer":"الجواب: يجب على المؤمن إذا رأى من أحدهم شيئًا أن ينصحه، إذا رأى منه تساهلًا، ولباسًا خفيفًا يظهر عورته، ينصحه، وينكر عليه هذا العمل؛ لأن هذا ما يجوز إقراره بين المؤمنين، فإذا رأى الإنسان من أخيه، أو من زوجته، أو من بنته، أو من أخته، أو رأى من صديقه، أو ممن يصلي في المسجد، أو في أي مكان؛ أنكر عليه. السؤال: الشُرَّاب هذا الرهيف الذي ما يستر الرِجْلَ يجوز المسح عليها؟ الجواب: لا، لابد أن يكون الشراب ساترًا. السؤال: حكم الصلاة بالثياب الخفيفة هذه التي تبان من تحتها العورة؟ الجواب: إذا الفخذ يظهر، أو العورة تظهر؛ تبطل الصلاة.","link":"https://binbaz.org.sa/fatwas/2888/حكم-الصلاة-بثياب-خفيفة-لا-تستر-العورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1336.mp3","categories":["ستر العورة للمصلي","قضايا المرأة"]},{"id":8146,"question":"هل يجوز لبس القصير -أي: ما تحت الركبة بقليل- بين النساء مع لبس الشراب أحياناً، أنا أعلم أن العورة المغلظة للمرأة من السرة إلى الركبة، ولكن هناك من يعارض لبس الشاميل أو الشاميل -لا أدري- أي: ما تحت الركبة فهل يجوز لبسه أم لا؟","title":"ما حد عورة المرأة مع المرأة وصفة لباسها بين النساء؟","answer":"الجواب: بين النساء لا حرج أن تلبس المرأة ما يغطي ما بين الركبة والسرة كالرجل بين الرجال عورته ما بين السرة والركبة عند الرجال، فهكذا المرأة عند النساء عورتها ما بين السرة والركبة، ولا حرج أن يرى النساء صدرها أو ساقها أو عضدها أو ساعدها أو رأسها كل هذا لا حرج فيه، لكن ينبغي أن يلاحظ هنا أن اعتيادها لهذا القصير قد يسبب تساهلها مع غير النساء فيراها الخادم ويراها السائق ويراها أخو زوجها أو عم زوجها ويراها غيره ممن يدخل في البيت فينبغي لها وهذه نصيحتي لكل امرأة أن تجتهد في اللباس المحتشم دائماً وأن تدع هذا التساهل لئلا يجرها هذا التساهل إلى فعله في مواطن لا ينبغي فعله فيها.\nوهذا أمر مجرب فإن العوائد قهارة فقد تعتاد هذا ثم تساهل به حينما تقابل أخا زوجها أو عم زوجها أو السائق أو الخادم في البيت وهذا منكر.\nفالأولى بها أن تكون ملابسها ساترة وضافية دائماً ويكون شعرها مستوراً إلا في حالة البيت الخاصة التي ليس فيها ما خطر الرجال ودخول الرجال.\nوالله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/5943/ما-حد-عورة-المراة-مع-المراة-وصفة-لباسها-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10402.mp3","categories":["ستر العورة للمصلي"]},{"id":8278,"question":"رسالة وصلت إلينا من المنطقة الشرقية، باعثتها إحدى الأخوات من هناك (ن.س.ع) تقول: ما حكم تغطية القدم أثناء الصلاة؟ وهل كشفه يؤثر على الصلاة أم لا؟","title":"حكم تغطية المرأة قدميها في الصلاة","answer":"الجواب: نعم نعم، على المرأة تغطي أقدامها في الصلاة عند جمهور أهل العلم، وقد ورد في هذا عند أبي داود حديث رفعه بعضهم ووقفه على أم سلمة آخرون، وهو أنها سئلت أم سلمة رضي الله عنها عن ذلك، عن تغطية المرأة أقدامها في الصلاة فقالت .. قالت السائلة: هل يجزيء المرأة أن تصلي في درع وخمار؟ فقالت أم سلمة: نعم، إذا كان الدرع سابغاً يغطي ظهور قدميها، وفي رواية عزت ذلك إلى النبي ﷺ.\nفالمقصود هو أن المرأة عليها أن تستر قدميها إما بإرخاء الثياب الطويلة وإما بالجورب، وليس لها أن تصلي وهي مكشوفة القدمين بل تكون الثياب ساترة طويلة، أو يكون عليها جوارب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6085/حكم-تغطية-المراة-قدميها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10002.mp3","categories":["ستر العورة للمصلي"]},{"id":8476,"question":"إحدى الأخوات المستمعات تقول: أم الحسن بعثت برسالة ضمنتها مجموعة من الأسئلة وفي هذه الحلقة تسأل وتقول: يقول عليه الصلاة والسلام: (المرأة كلها عورة إلا يديها ووجهها في الصلاة) أو كما جاء عنه ﷺ، هل يعني هذا أنه يجب على المرأة تغطية حتى قدميها إذا كان لبسها ساتر ولا يظهر منها إلا القدمان، هل يجب عليها تغطيتها أيضاً بلبس جورب أو لا يجب ذلك؟","title":"حد عورة المرأة في الصلاة","answer":"الجواب: هذا الكلام ليس حديثاً عن النبي ﷺ، ولكنه من كلام بعض الفقهاء، يقولون: المرأة عورة إلا وجهها في الصلاة، وقال آخرون: إلا وجهها وكفيها، وهذا قول معروف عند أهل العلم.\nوقال آخرون: إلا وجهها وكفيها وقدميها أيضاً. والأكثر من أهل العلم على أن قدميها عورة في الصلاة، وأن الواجب ستر القدمين وهذا قول أكثر أهل العلم.\nأما الكفان: فالأولى سترهما فإن لم تسترهما فلا حرج إن شاء الله.\nوأما الوجه: فالسنة كشفه في الصلاة إلا أن يكون عندها أجنبي فإنها تستره ولو في الصلاة؛ لأنها فتنة ولأن الوجه أعظم زينتها، عملاً بقول الله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] فالآية عامة لأزواج النبي صلى الله عليه وسلم، ولغيرهن من المؤمنين والمؤمنات، الآية عامة تعم أزواج النبي ﷺ وتعم جميع نساء المؤمنين، كما قال : يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59].\nنعم ورد حديث رواه أبو داود في هذا المعنى عن عائشة رضي الله عنها: أن أسماء بنت أبي بكر -يعني: أخت عائشة رضي الله عن الجميع- دخلت على عائشة وعندها الرسول ﷺ قالت: وعليها ثياب رقاق، فأعرض عنها النبي ﷺ وقال: يا أسماء إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها غير هذا وهذا، وأشار إلى وجهه وكفيه عليه الصلاة والسلام هذا الحديث احتج به بعض من يرى جواز السفور ويحل للمرأة كشف وجهها عند الرجال، ولكنه حديث ضعيف لا يصح عن النبي ﷺ، قد غلط بعض الناس فظن أنه صحيح، والصواب: أنه ضعيف لعدة علل تدل على ضعفه.\nمنها: أن الذي رواه عن عائشة لم يسمع من عائشة وهو خالد بن دريك فإنه لم يلق عائشة ولم يدركها، فهو منقطع والمنقطع عند أهل العلم ضعيف لا يحتج به.\nومنها: أن في إسناده راوياً يقال له: سعيد بن بشير ، وهو ضعيف عند أهل العلم لا يحتج بروايته.\nومنها: أنه من رواية قتادة بن دعامة السدوسي عن خالد بن دريك وقد عنعنه وهو مدلس، والمدلس لا يحتج بروايته إذا لم يصرح بالسماع.\nوعلى فرض صحته يمكن أن يكون هذا قبل نزول آية الحجاب، فإن النساء كن في عهد النبي ﷺ يكشفن ويجلسن مع الرجال حتى أنزل الله آية الحجاب، فلو قدرنا صحة الحديث لكان محتملاً أن يكون قبل نزول آية الحجاب؛ لأنه ليس في الحديث ذكر آية الحجاب.\nولكن يكفينا أنه ضعيف، ضعيف الإسناد لا يصح عن النبي ﷺ فلا يجوز التعلق به، والمشروع للنساء بل الواجب على النساء الحجاب والتستر عن الرجال في جميع الأحوال، ومن ذلك الوجه فإنه زينة المرأة بل هو أعظم زينتها.\nفالواجب الحجاب والتستر في جميع المجالات التي يكون فيها رجل غير محرم.\nأما في الصلاة: فالسنة كشف الوجه، إذا كان ليس هناك رجل أجنبي، تصلي مكشوفة الوجه هذا هو السنة وإن كشفت الكفين فلا بأس، وسترهما أولى.\nأما القدمان فالذي عليه جمهور أهل العلم هو سترهما، إما بالجوربين أو بالملابس الضافية التي تستر القدمين، وقد خرج أبو داود رحمه الله عن أم سلمة رضي الله عنها أنها سئلت: هل تصلي المرأة في درع وخمار؟ فقالت: إذا كان الدرع سابغاً يغطي ظهور قدميها، وقد روي هذا مرفوعاً وموقوفاً، لكن قال الحافظ ابن حجر: أن الأئمة رجحوا وقفه على أم سلمة ، وبكل حال فهو دليل على ما قاله جمهور أهل العلم من وجوب تغطية القدمين في الصلاة، إما بثياب ضافية وإما بجوربين، وفق الله الجميع.\nالمقدم: جزاكم الله خيراً، إن لم يحدث هذا سماحة الشيخ إن لم تغط المرأة قدميها أو صلت في غرفتها بمفردها، هل يلزم أيضاً تطبيق هذا؟\nالشيخ: نعم عليها أن تغطي قدميها مطلقاً ولو كان ما عندها رجال؛ لأنهما عورة في الصلاة، نعم هذا الذي عليه جمهور أهل العلم. نعم.\nالمقدم: بارك الله فيكم، وإن لم يحصل هذا فما حكم صلاتها؟\nالشيخ: عليها أن تعيد.\nالمقدم: عليها أن تعيد الصلاة؟\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6513/حد-عورة-المراة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12503.mp3","categories":["ستر العورة للمصلي"]},{"id":8498,"question":"ما الحدود التي تستطيع المرأة المسلمة كشفها أمام المرأة الكافرة كالبوذية مثلاً، وهل صحيح أنه لا يجوز لها إلا كشف وجهها وكفيها؟","title":"حد عورة المرأة المسلمة مع المرأة الكافرة","answer":"الجواب: الصحيح أن المرأة تكشف للمرأة سواء كانت مسلمة أو كافرة هذا هو الصحيح، ما فوق السرة وتحت الركبة، أما ما بين السرة والركبة فهو عورة للجميع لجميع النساء لا تراه المرأة، سواء كانت مسلمة أو غير مسلمة قريبة أو بعيدة ما بين السرة والركبة، كالعورة للرجل مع الرجال بين السرة والركبة، فللمرأة أن ترى من المرأة صدرها ورأسها وساقها ونحو ذلك لا بأس في هذا، كالرجل يرى من الرجل صدره وساقه ورأسه ونحو ذلك.\nوأما قول بعض أهل العلم أن المرأة الكافرة لا يكشف لها فهو قول مرجوح، ذهب إليه بعض أهل العلم، قالوا: إنها كالرجل لقوله تعالى: أَوْ نِسَائِهِنَّ [النور:31] ولكن الصواب أن المراد بـ نِسَائِهِنَّ: يعني جنس النساء، مسلمات أو كافرات لا حرج في إبداء الزينة لهن هذا هو الصواب.\nوقد كانت اليهوديات في المدينة في عهد النبي ﷺ وهكذا الوثنيات يدخلن على أزواج النبي ﷺ لحاجتهن فلم يحفظ أنهن كن يستترن منهن رضي الله عنهن وأرضاهن، وهن أتقى الناس أزواج النبي ﷺ هن أتقى الناس وأفضل النساء ومع هذا ما كن فيما بلغنا يستترن عمن يدخل عليهن من اليهوديات ونحوهن.\nفالحاصل: أن المرأة لا بأس أن تكشف للمرأة الكافرة كما تكشف للمسلمة، وليس عليها أن تحتجب عن النساء الكافرات، هذا هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/6558/حد-عورة-المراة-المسلمة-مع-المراة-الكافرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12612.mp3","categories":["ستر العورة للمصلي"]},{"id":8809,"question":"أختنا تسأل مع من يسأل من أخواتنا المستمعات سماحة الشيخ عن تغطية اليدين والرجلين في الصلاة هل هو واجب على المرأة أم يجوز كشفها ولاسيما إذا لم يكن هناك أجانب أو كانت في الصلاة مع نساء؟","title":"حكم كشف المرأة للوجه واليدين والرجلين في الصلاة","answer":"الجواب: أما الوجه فالسنة كشفه في الصلاة إذا لم يكن هناك أجانب، السنة كشفه في الصلاة، وأما القدمان فالواجب سترهما عند جمهور أهل العلم عند الأكثر من أهل العلم الواجب سترهما وفيه خلاف؛ بعض أهل العلم يسامح في القدمين ولكن الجمهور على المنع وأن الواجب سترهما، ولهذا روى أبو داود رحمه الله عن أم سلمة رضي الله عنها أنها سئلت عن المرأة تصلي في خمار وقميص؟ قالت: لا بأس إذا كان الدرع يغطي ظهور قدميها فستر القدمين أولى وأحوط بكل حال.\nأما الكفان فأمرهما أوسع، إن كشفتهما فلا بأس وإن سترتهما فلا بأس الأمر فيهما واسع، بعض أهل العلم يرى أن سترهما أولى ولكن الأمر فيهما واسع، إن سترتهما فهذا حسن إن شاء الله وإن صلت وكفاها مكشوفتان فلا بأس.\nالمقدم: بارك الله فيكم، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6964/حكم-كشف-المراة-للوجه-واليدين-والرجلين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_135/13505.mp3","categories":["ستر العورة للمصلي"]},{"id":8872,"question":"شيخ عبدالعزيز! أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ محمد يوسف محمد الجندي العراق الحلة الطهمزية، مصري، أخونا بدأ رسالته كالتالي يقول:إلى أصحاب الفضيلة العلماء كافة وبالأخص فضيلة الوالد عبد العزيز بن عبدالله بن باز، السلام عليكم ورحمة الله وبركاته، ندعو الله لكم بالتوفيق الدائم لما فيه الخير للإسلام والمسلمين، وندعوه أن يوفقكم على الدوام بقدر ما استفدناه منكم، رعاكم الله.سماحة الشيخ! سمعناكم ذات مرة تتحدثون في جواب عن صلاة المرأة وهي تصلي دون ستر يديها وقدميها أنها لابد أن تعيد صلاتها كلها، فأرجو الإفادة، حول هذا الموضوع، وكيف؟ علمًا بأننا مستقيمون على دين الله وتطبيق شريعته منذ زواجنا في أربعة وثمانين ميلادي، ومن يوم أن سمعنا تلكم الحلقة وهي تستر قدميها وكفيها؟","title":"حكم ستر القدمين واليدين والوجه في الصلاة للمرأة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن العلماء رحمة الله عليهم قد نصوا على أن المرأة عورة، وأن الواجب عليها ستر بدنها في الصلاة ما عدا وجهها، وهذا بناء على ما جاء في الأحاديث عن رسول الله ﷺ من بيان أن المرأة عورة، واختلفوا في الكفين هل يستران أم يعفى عنهما، وأما القدمان فجمهور العلماء على أنهما يستران في الصلاة، وأما الوجه فقد أجمعوا على أنه لا مانع من كشفه وأن السنة كشفه في الصلاة إذا لم يكن عندها أجنبي -يعني: رجل غير محرم- فهذا هو المعتمد في هذا الباب أن المرأة عليها أن تستر بدنها كله ما عدا وجهها وكفيها.\nوالصحيح: أن الكفين لا يجب سترهما في الصلاة لكن سترهما أفضل خروجًا من خلاف من أوجب سترهما، وأما القدمان فالواجب سترهما عند جمهور أهل العلم؛ لأن المرأة عورة وهما من العورة ولا داعي إلى كشفهما، تسترهما بالجورب -جوربين- أو بالملابس الضافية التي تستر القدمين حال الصلاة، هذا هو الذي سبق مني غير مرة وبينته لإخواني في هذا البرنامج نور على الدرب، أن الواجب على المرأة أن تستر بدنها بالستر الكافي الذي لا يبين معه شيء من بدنها، يكون سترًا كافيًا ليس رقيقًا ولا شفافًا بل يكون سترًا يغطي شعرها وبدنها ما عدا الوجه فإن السنة كشفها له إذا كانت ليس عندها رجل غير محرم.\nوأما الكفان فاختلف العلماء فيهما، والأفضل سترهما فإن كشفتهما فلا حرج، وأما القدمان مثل ما تقدم سترهما هو الواجب.\nوأما كونها تقضي ما مضى من صلاتها فهذا من باب أنها أخلت بالشرط، فإذا كانت صلت صلوات ليست ساترة لقدميها فيها فإن الواجب قضاؤها، لكن إذا كانت جاهلة بالحكم الشرعي فلعل الله جل وعلا يعفو عنها فيما مضى ولا يكون عليها قضاء، وقد صح عنه عليه الصلاة والسلام أنه لما رأى رجلًا يصلي وينقر صلاته دعاه فقال له- بل جاءه وسلم عليه- فقال له: ارجع فصل؛ فإنك لم تصل، فرجع فصلى كما صلى، ثم جاء فسلم على النبي عليه الصلاة والسلام فرد عليه السلام ثم قال له: ارجع فصل؛ فإنك لم تصل، فرجع فصلى كما صلى، ثم جاء في الثالثة فسلم على النبي ﷺ، فرد عليه النبي السلام ثم قال له: ارجع فصل؛ فإنك لم تصل، فعلها ثلاثًا، فقال الرجل: والذي بعثك بالحق نبيًا لا أحسن غير هذا فعلمني، فقال له عليه الصلاة والسلام: إذا قمت إلى الصلاة فأسبغ الوضوء ثم استقبل القبلة فكبر، ثم اقرأ ما تيسر معك من القرآن، ثم اركع حتى تطمئن راكعا، ثم ارفع حتى تعتدل قائما، ثم اسجد حتى تطمئن ساجدا، ثم ارفع حتى تطمئن جالسا، ثم اسجد حتى تطمئن ساجدا، ثم افعل ذلك في صلاتك كلها متفق على صحته.\nفأمره النبي ﷺ أن يعيد هذه الصلاة الحاضرة، ولم يأمره أن يعيد الصلوات الماضية لجهله، فإن ظاهر حاله أنه يصلي هذه الصلاة فيما مضى، ولكن لما كان جاهلًا عذره ﷺ في الأوقات الماضية وأمره أن يعيد الحاضرة، فدل ذلك على أن من جهل شيئًا من فرائض الصلاة ثم نبه في الوقت الحاضر فإنه يعيد الحاضرة، أما التي مضت فتجزئه من أجل الجهل، هذا هو مقتضى هذا الحديث؛ لأن الرسول ﷺ لم يأمر هذا المسيء في صلاته أن يعيد صلواته الماضية بسبب جهله وما في ذلك من المشقة.\nفهكذا التي صلت صلوات كثيرة قبل أن تعلم وجوب ستر القدمين فإنها لا إعادة عليها إن شاء الله على الصحيح؛ لأنها معذورة بالجهل، وإنما تلتزم في المستقبل وتستقيم في المستقبل على ستر قدميها وبقية بدنها ما عدا الوجه والكفين كما تقدم فإنهما ليسا عورة في الصلاة عند أهل العلم، ولكن إذا سترت الكفين خروجًا من خلاف بعض أهل العلم فهذا حسن كما تقدم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7028/حكم-ستر-القدمين-واليدين-والوجه-في-الصلاة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_167/16701.mp3","categories":["ستر العورة للمصلي"]},{"id":8953,"question":"سؤالها الثاني: هل يجوز صلاة المرأة في جلباب ضيق ولكنه لا يشف -أي: أنه من قماش ليس خفيفاً- مع ارتداء الجورب والخمار؟","title":"حكم صلاة المرأة بالجلباب الضيق غير الشفاف","answer":"الجواب: نعم، الصلاة صحيحة، لكن مهما كان الجلباب واسعاً يريح المرأة في صلاتها وتطمئن إلى أنه يستر قدميها فهذا أولى، وإلا فالمقصود هو الستر، متى ستر وإن كان ضيقاً حصل المقصود. نعم.","link":"https://binbaz.org.sa/fatwas/7111/حكم-صلاة-المراة-بالجلباب-الضيق-غير-الشفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_173/17303.mp3","categories":["ستر العورة للمصلي"]},{"id":9202,"question":"هذه رسالة وصلت إلى البرنامج من ليبيا وباعثها أحد الإخوة المستمعين من هناك يقول: (خ. غ. غ) من بن غازي، يسأل أولًا ويقول: ما حكم امرأة صلت في الخلاء لعذر مثل: السفر أو البعد عن البلاد وهي غير محتجبة الحجاب الشرعي؟","title":"حكم صلاة المرأة في الخلاء دون التحجب بالحجاب الشرعي","answer":"الجواب: إذا كانت ليس عندها أحد من الناس فلا بأس، فالحجاب الشرعي إنما يلزم عند وجود الأجنبي فإذا صلت في الصحراء أو في بيتها أو في سقف بيتها أو في حوش بيتها وليس عندها أجنبي فلا بأس أن تكشف وجهها وتصلي مكشوفة الوجه، لكن عليها مهما كانت أن تستر شعرها وجميع بدنها في الصحراء وفي غير الصحراء حتى ولو كانت ما عندها أحد في بيتها عليها أن تستر جميع بدنها من الشعر وسائر البدن والقدمين حتى تكون مستورة محجبة الحجاب الشرعي؛ لقول النبي ﷺ: لا يقبل الله صلاة حائض إلا بخمار، فلابد من ستر شعرها إن كانت الجارية بالغة، أما الوجه فلا بأس بكشفه، السنة كشفه في الصلاة إذا كان ما عندها أحد من الأجنبيين ما عندها رجل أجنبي يحرم عليها الكشف له، كأخي زوجها أو ابن عمها أو زوج أختها هؤلاء أجناب، يعني: لا تكشف لهم وإن كانوا قريبين منها من جهة المصاهرة ونحوها، لكنهم في حكم الشرع أجنبي يسمى أجنبيًا لأنه ليس محرمًا يعني، وهكذا كفاها لو سترتهما يكون أفضل في الصلاة وإن صلت وهما مكشوفان فلا بأس بذلك على الصحيح كالوجه، لكن سترهما يكون أفضل، وأما القدمان فيجب سترهما عند جمهور أهل العلم، بالجوربين أو بالثياب الضافية المرأة تستدل ثيابها عليهما، أو بجوربين فيهما كل هذا يكفي. نعم.\nالمقدم: بارك الله فيكم، إذًا الأم عند أولادها وعند زوجها في بيتها لا يلزمها هذا أو يلزم لكن فيما لو صلت فالصلاة صحيحة؟\nالشيخ: صلاتها صحيحة لكن بشرط أن تكون العورة مستورة، من الرأس والصدر والبطن والساق ونحو ذلك والقدم حتى لا تكون هناك يعني مخالفة للشريعة، أما الوجه والكفان مثلما تقدم لا يجب سترهما إلا عند الأجنبي، سواءً كانت في الصحراء أو في البيت.\nالمقدم: أما القدم فالقدم .... ؟\nالشيخ: الواجب يستر عند جمهور أهل العلم. نعم.\nالمقدم: سواءً عند المحارم أو غيره أو ....\nالشيخ: نعم .. نعم مطلقا يستر في الصلاة بالجوربين أو بالثياب الضافية السابغة. نعم.\nالمقدم: وفيما لو صلت على غير هذه الصورة؟\nالشيخ: تعيد، تعيد الصلاة.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7362/حكم-صلاة-المراة-في-الخلاء-دون-التحجب-بالحجاب-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18110.mp3","categories":["ستر العورة للمصلي"]},{"id":9502,"question":"السؤال الثالث في هذه الرسالة يقول: هل يجوز للرجل أن يصلي داخل بيته في سراويل وفنيلة مغطيتان للعورة أم يلزمه لبس ثيابه والتجمل مع الغترة ونحوها؟","title":"حكم الصلاة في السراويل والفنيلة في البيت","answer":"الجواب: الصلاة في السراويل وفي الفنيلة الساترة للمنكبين صحيحة، ولا بأس إذا كان السراويل ساترة للعورة والفنيلة ساترة للمنكبين، كل هذا لا حرج فيه لقول النبي ﷺ: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء فإذا كان على العاتق أو العاتقين شيء كالفنيلة فالحمد لله، ولكن كونه يتجمل يلبس قميصه وعمامته يكون أفضل؛ لقوله سبحانه: يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31] كونه يأخذ الزينة المعتادة ويصلي مع الناس بالملابس الحسنة كل هذا أفضل، ولكن إذا صلى في إزار ورداء، أو صلى في قميص ورداء، أو قميص وفنيلة ساترة للمنكبين فلا بأس بذلك ولا حرج، فالصلاة صحيحة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7678/حكم-الصلاة-في-السراويل-والفنيلة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24312.mp3","categories":["ستر العورة للمصلي"]},{"id":9657,"question":"الرسالة التالية وصلت من المستمعة التي تقول بأن اسمها (إستبرق . ع. ز. ذ) العنوان: العراق- بغداد، الرسالة تحتوي على العديد من الأسئلة: السؤال الأول تقول فيه: هل يجوز إسدال الشعر على الجبين في الصلاة من المرأة أفيدونا أفادكم الله؟","title":"حكم إسدال المرأة شعرها على جبينها في الصلاة","answer":"الجواب: لا نعلم به شيئًا لكن إذا أزالته وصار السجود على نفس الجبهة لعله يكون أحسن ...... ..... لأنه جزء منها لا يضرها مثل لو سجد على العمامة الرجل أو على غير ذلك من بساط أو سجادة لا يضر. نعم .\nهذا يحتاج إلى تأمل؛ لأن الشعر عورة فلابد من ستره إذا سجدت عليه وهو مستور لابأس، أما كونه ... لا لا يجوز؛ لأن عليها أن تستر شعرها فهو عورة إذا كانت قد بلغت المحيض قد بلغت الحلم فالواجب عليها ستر رأسها وأن لا يبدو منها إلا الوجه والكفان لابأس بهما أيضًا، وأما الشعر فيجب ستره لقوله ﷺ: لا يقبل الله صلاة حائض إلا بخمار فعليها أن تستر شعرها وجميع بدنها ما عدا الوجه والكفين وإن سجدت على بعض الشعر وهو مستور مثلًا تحت خمار لها مستور بالخمار لا يضر لكن ينبغي لها أن ترفعه عن وجهها وأن تسجد على الجبهة ويكون الشعر مستورًا هذا الواجب عليها، شرط في الصلاة. نعم.","link":"https://binbaz.org.sa/fatwas/7823/حكم-اسدال-المراة-شعرها-على-جبينها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19413.mp3","categories":["ستر العورة للمصلي"]},{"id":9805,"question":"وهذه رسالة وردتنا من السائل شرف الدين عبدالله السياني من أبناء الجمهورية العربية اليمنية، يقول في رسالته: هناك بعض الناس يصلون في ثوبٍ خفيف جدًا وبدون سراويل طويل؛ وإنما سروال صغير جدًا، فهل صلاتهم صحيحة وبماذا ننصحهم؟","title":"حكم الصلاة بالثوب الشفاف","answer":"الجواب: إذا كان الذي يصلي رجل فالواجب أن يستر ما بين السرة والركبة، وأن يكون عليه سراويل ساترة، أو قميص ساتر، وإذا كان ثوبه خفيف يبين معه الفخذ -لحمة الفخذ- يعرف سوداء أو حمراء، فهذا اللباس لا يستر ولا يجزي، ولا تصح الصلاة معه، كأنه مكشوف.\nأما إذا كان اللباس يستر الفخذين والعورة ولكنه خفيف وهو يستر فلا يضر، أو كان عليه سراويل وافية تستر ما بين السرة والركبة فلا يضر، أو إزار ساتر.\nأما المرأة فيجب أن تستر بدنها كله في الصلاة، يجب أن تكون ملابسها ساترة، صفيقة، لا يرى بدنها؛ وإنما تكشف وجهها فقط في الصلاة، وإن كشفت الكفين فلا بأس؛ لكن الأفضل ستر الكفين أيضًا، ولا يجوز لها أن تصلي في أثواب خفيفة يرى منها لحمها ويعرف هل هو أحمر أو أسود، هذا حكمه حكم العارية، ما تصح صلاتها. نعم.","link":"https://binbaz.org.sa/fatwas/7972/حكم-الصلاة-بالثوب-الشفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19704.mp3","categories":["ستر العورة للمصلي"]},{"id":9842,"question":"هذه رسالة من أسماء عبدالملك من العراق، تقول في رسالتها: ذهبت لزيارة أختي فقمت أصلي وأثناء الصلاة دخل علي أخو زوج أختي، وكرر الدخول في الغرفة ثلاث مرات أثناء الصلاة لحاجة ضرورية، فهل علي إعادة الصلاة أم لا؟","title":"حكم صلاة المرأة عند غير المحارم","answer":"الجواب: ليس عليك إعادة الصلاة الحمد لله، إذا كنت قد صليت كما شرع الله، بالستر والطمأنينة، وأديت الصلاة على الوجه الشرعي فدخوله لا يبطلها، دخوله عليك لا يبطل الصلاة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8012/حكم-صلاة-المراة-عند-غير-المحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26204.mp3","categories":["ستر العورة للمصلي","قضايا المرأة"]},{"id":10091,"question":"رسالة بعث بها مستمعة، تقول المستمعة (هـ. ز) من مصر الفيوم، قرأت أن عورة المرأة على المرأة وكذلك الرجل على الرجل من السرة إلى الركبتين، فما هي السن التي إذا بلغها الشخص لا يجوز عنده كشف عورته، وكذلك رؤية عورة الغير، جزاكم الله خيرًا؟","title":"ما السن الذي إذا بلغه الشخص لا يجوز عنده كشف العورة؟","answer":"الجواب: العورة للرجل ما بين السرة والركبة عند الرجال، والعورة للمرأة بين النساء ما بين السرة والركبة، فالواجب على الرجل أن يستر عورته، وإذا كان في الصلاة أمر أيضًا أن يضع على عاتقيه شيء؛ لقوله ﷺ: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء، أما المرأة فعليها أن تستر بدنها كله في الصلاة، رأسها ويداها يعني ذراعها، وهكذا عضدها، وهكذا رجلاها عليها ستر الجميع، إلا الكفين فلا حرج في إبدائهما وسترهما أفضل، أما الوجه فتكشفه، وإذا كانت ليست بالغة فلا حرج أن تكشف رأسها، يكون رأسها غير عورة ليس بعورة؛ لقول ﷺ: لا يقبل الله صلاة حائض إلا بخمار، فدل على أنه إذا كان ما بعد بلغت لا يشترط ستر رأسها، وأما إذا كانت قد بلغت خمسة عشر سنة أو حاضت أو أنبتت الشعر الخشن حول الفرج، أو أنزلت المني بالاحتلام عند الشهوة أو عند الملامسة تكون قد بلغت، فلابد من سترها جميع بدنها إلا الوجه وإلا الكفين على الأرجح الكفين، وإن سترتهما فهو أفضل، وفق الله الجميع. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8260/ما-السن-الذي-اذا-بلغه-الشخص-لا-يجوز-عنده-كشف-العورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_276/27619.mp3","categories":["ستر العورة للمصلي"]},{"id":10311,"question":"ما حكم تغطية القدمين في الصلاة بطبيعة الحال للنساء؟","title":"حكم تغطية القدمين في الصلاة","answer":"الجواب: كذلك تغطى القدمان في الصلاة عند جمهور العلماء، لما روى أبو داود عن أم سلمة رضي الله عنها أنها سئلت: هل تصلي المرأة في درع وخمار؟ قالت رضي الله عنها: نعم إذا كان القميص يغطي ظهور قدميها فالمقصود: أنها تغطي قدميها وقت الصلاة كما تغطيهما عند الرجل الأجنبي هذا هو المختار وعليه جمهور أهل العلم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8481/حكم-تغطية-القدمين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_313/31307.mp3","categories":["ستر العورة للمصلي"]},{"id":10370,"question":"إذا صلت المرأة في بيتها لوحدها فهل تصح صلاتها في الملابس الضيقة؟","title":"حكم صلاة المرأة بالملابس الضيقة إذا كانت في بيتها","answer":"الجواب: إذا كانت ساترة للعورة لا بأس، لكن الأفضل والسنة أن تكون ملابسها وسطًا لا ضيقة ولا واسعة جدًا، ولكن بين ذلك، لكن لو صلت في ملابس ضيقة ولكنها ساترة لجميع بدنها ما عدا الوجه والكفين فإن الصلاة صحيحة، والأفضل ستر الكفين فإن لم تسترهما فلا حرج في ذلك إن شاء الله كالوجه، إذا لم يكن عندها أجنبي.\nوالخلاصة: أن صلاتها صحيحة لكن ينبغي لها أن تعتاد اللبس الوسط، الذي ليس بالضيق جدًا وليس بالواسع جدًا بل بين ذلك؛ لأن الضيق يبين حجم أعضائها ويبين حجم العورة، فلا ينبغي للمرأة ولا يليق بها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8542/حكم-صلاة-المراة-بالملابس-الضيقة-اذا-كانت-في-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33903.mp3","categories":["ستر العورة للمصلي"]},{"id":10653,"question":"السائلة من مدينة الزلفي المستمعة (خ. محمد ) تقول: أسأل سماحة الشيخ عن حكم لبس القفاز لليدين في الصلاة في المسجد أثناء شهر رمضان المبارك؟ جزاكم الله خيرًا.","title":"حكم لبس المرأة للقفازين أثناء الصلاة","answer":"الجواب: نعم، هذا هو الأفضل، أن تستر كفيها، في البيت وفي المسجد هذا هو الأفضل، ولو صلت مكشوفة الكفين ولكن لا يراها الرجال صح، والسنة كشف الوجه إذا كان ما يراها الرجال كشف الوجه، أما إذا كان يراها الرجال تستر وجهها وكفيها جميعًا مع بقية بدنها، أما إذا كانت في البيت فإنها تستر بقية البدن ما عدا الوجه، فالسنة كشف الوجه، إذا كان عند النساء أو ما عندها أحد، وأما الكفان فالأفضل سترهما إذا كان ما عندها أحد بالقفازين وإن كشفتهما فلا حرج إذا كان ما عندها إلا نساء أو ما عندها أحد. نعم.","link":"https://binbaz.org.sa/fatwas/8830/حكم-لبس-المراة-للقفازين-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28515.mp3","categories":["ستر العورة للمصلي"]},{"id":10792,"question":"رسالة وصلت إلى البرنامج من العراق، محافظة الأنبار، باعثها مستمع من هناك هو حماد حمد علي، عرضنا بعض أسئلة له في حلقة مضت، وبقي له في هذه الحلقة سؤال واحد يقول فيه: أرجو التوضيح مفصلًا عن مسألة وجوب ستر الوجه والكفين بالنسبة للمرأة، وهل تصح صلاتها إذا كشفت عن وجهها وكفيها في الصلاة، حيث هذا السؤال قد شغل كثيرًا من النساء في بلدنا؛ لأنهن يخرجن إلى المدينة بحجاب مع ظهور الوجه والكفين، مستشهدين بأحاديث صحيحة عن الرسول ﷺ أفتونا جزاكم الله خيرًا.","title":"حكم ستر المرأة لوجهها وكفيها في الصلاة وخارجها","answer":"الجواب:  أما في الصلاة فإنها تكشف وجهها وكفيها لا حرج، إذا لم يكن عندها أجنبي، فإنها تصلي مكشوفة الوجه، هذا هو السنة، وتستر بقية بدنها، كرأسها، وصدرها، وجميع بدنها، ومن ذلك قدماها، عليها ستر الجميع، أما الكفان فإن سترتهما فهو أفضل، كما قاله جمع من أهل العلم، وإن أبدتهما فلا حرج في ذلك على الصحيح. وأما الوجه فإنه يكشف في الصلاة وتصلي مكشوفة الوجه إلا إذا كان عندها أجنبي كأخي زوجها، أو زوج أختها، أو غيرهما فإنها تستر وجهها وكفيها وقت الصلاة من أجلهم، من أجل غير المحرم. وهكذا إذا خرجت الأسواق تستر بدنها كله؛ لأنها عورة وفتنة والله يقول -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وقال جل وعلا: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ [النور:31] الآية. والزينة يدخل فيها الوجه والشعر وسائر بدنها كلها زينة، والوجه أعظم الزينة، وهو مجمع محاسن الخلقة. أما الأحاديث التي أشار لها السائل في كشف الوجه فكان هذا في أول الأمر، في أول الإسلام كانت المرأة تكشف، وتجلس مع الرجال مكشوفة الوجه، ثم أمر الله -جل وعلا- بالحجاب، ونزلت آية الحجاب التي سبق ذكرها، وهي قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53] الآية، ومن ذلك آية النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] الآية. ومن ذلك قوله -جل وعلا- أيضًا في سورة الأحزاب: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] ومن ذلك قوله في سورة النور، يقول سبحانه: وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60]. فإذا كان القواعد وهن العجائز اللاتي لا يردن نكاحًا استعفافهن أفضل، وهو تحجبهن، ويجوز لهن عدم التحجب لكونهن عجائز، لا يطمع فيهن، فالشابات من باب أولى أن يستعففن، وأن يلزمن الحجاب؛ لأنهن فتنة، وذكر القواعد يدل على أن غير القواعد يلزمهن الحجاب، والاستعفاف. فالمقصود أن الأحاديث التي فيها كشف الحجاب، هذه كانت في أول الإسلام، وفي أول مجيء المسلمين إلى المدينة، ثم بعد ذلك أنزل الله آيات الحجاب، ومنع النساء من إظهار زينتهن، ومن ذلك ما ثبت في الصحيحين عن عائشة -رضي الله عنها- في قصة الإفك، لما مر عليها صفوان المعطل قد تخلفت عن الغزو، وقد ذهبت تقضي حاجة لها، فحملوا هودجها يظنونها فيه لخفتها، فلما رآها استرجع، فلما سمعت صوته خمرت وجهها، قالت: وكان قد رآني قبل الحجاب. فدل ذلك على أنهن قبل الحجاب كن يكشفن الوجوه، وبعد الحجاب أمرن بستر الوجوه. وأما حديث عائشة -رضي الله عنها- في قصة أسماء بنت أبي بكر أنها دخلت على النبي ﷺ وعليها ثياب رقاق، فأعرض عنها النبي -عليه الصلاة والسلام- وقال: يا أسماء ! إن المرأة إذا بلغت المحيض لم يصلح أن يرى منها إلا هذا وهذا، وأشار إلى الوجه والكفين أخرجه أبو داود، هو حديث ضعيف عند أهل العلم، لعلل ثلاث: إحداها أنه من رواية خالد بن دريك، عن عائشة، ولم يسمع منها، منقطع. والعلة الثانية: أن في إسناده سعيد بن بشير، وهو ضعيف الرواية. والعلة الثالثة: أنه من رواية قتادة، عن خالد بالعنعنة، وهو مدلس، والمدلس لا تقبل روايته إذا عنعن حتى يصرح بالسماع، إلا ما كان في الصحيحين من رواية المدلسين فإنه محمول على السماع. وهناك وجه رابع: وهو أنه إذا صح لكان محمولًا على ما كان قبل الحجاب، لكان هذا مع أسماء قبل الحجاب، أما بعد الحجاب فإن المرأة مأمورة بالستر لوجهها، وجميع بدنها، لما تقدم في الآيات السابقات، والله ولي التوفيق. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8970/حكم-ستر-المراة-لوجهها-وكفيها-في-الصلاة-وخارجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_351/35107.mp3","categories":["ستر العورة للمصلي"]},{"id":10897,"question":"تقول: ألبس فستانًا يكشف عن وجه القدم، هل تجوز الصلاة فيه؟","title":"حكم كشف المرأة ظهور قدميها في الصلاة","answer":"الجواب:  لا، الواجب عند جمهور أهل العلم أن يكون القدم مستورًا، إما بالثياب الضافية، وإما بالجوارب، وهكذا جاء عن أم سلمة -رضي الله عنها- لما سئلت قيل: \"يا أم المؤمنين! هل تصلي المرأة في درع وخمار؟ فقالت: إذا كان الدرع سابغًا يغطي ظهور قدميها\".  فالذي عليه جمهور أهل العلم: أن المرأة عورة في الصلاة كلها، المرأة كلها عورة في الصلاة إلا وجهها فإنه لا بأس بكشفه، بل يسن كشفه في الصلاة إذا لم يكن عندها أجنبي يعني: غير محرمها، أما الكفان ففيهما خلاف بين أهل العلم. والصواب: أن لا حرج في كشفهما، فإن سترتهما كان ذلك أفضل، وأما القدمان فالواجب سترهما إما بالملابس الضافية كالقميص الضافي، والإزار الضافي، أو بالجوارب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9083/حكم-كشف-المراة-ظهور-قدميها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36010.mp3","categories":["ستر العورة للمصلي"]},{"id":10965,"question":"هل تتفضلون سماحة الشيخ ببيان حكم الحجاب أثناء تأدية الصلاة بالنسبة للمرأة؟","title":"كيفية حجاب المرأة أثناء الصلاة","answer":"الجواب:  نعم، عليها أن تستتر في كل بدنها ما عدا الوجه والكفين، الواجب على المرأة أن تكون مستورة في جميع بدنها حال الصلاة حتى القدمين، عليها أن تكون الثياب ضافية تستر القدمين، أو يكون على القدمين خفان، أو جوربان، أما الوجه فلا يجب ستره بإجماع المسلمين، بل الأفضل كشفه، الوجه تكشفه في الصلاة إذا كانت خالية ليس عندها أجنبي، عليها أن تكشف وجهها، تصلي مكشوفة الوجه، هذا هو السنة، وهذا هو الأفضل، إلا إذا كان عندها رجل ليس محرمًا لها، فإنها تغطيه عنه، وأما الكفان فالأفضل سترهما، وإن كشفتهما فلا حرج -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9143/كيفية-حجاب-المراة-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_364/364010.mp3","categories":["ستر العورة للمصلي"]},{"id":10981,"question":"السائلة: (ن. ع) من جدة تقول: هل يجب على المرأة عندما تضع الشرشف على رأسها وقت الصلاة أن تبين الجهة؛ لأنهم يقولون: لا بد من ظهورها أثناء الصلاة وجهونا بهذا؟","title":"حكم تغطية المرأة لوجهها في الصلاة","answer":"الجواب:  لا حرج، لكن الأفضل ظهور الوجه كله، إن كان ما عندها أحد، السنة أن يكون وجهها مكشوفًا، إن كان في بيتها، أو بين النساء السنة يكون مكشوف الوجه، مكشوفة الوجه، وأما إذا كانت عند الرجال تستر وجهها كله، وتسجد على الخمار، والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/9159/حكم-تغطية-المراة-لوجهها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28702.mp3","categories":["ستر العورة للمصلي"]},{"id":11023,"question":"تسأل أختنا أيضًا وتقول: هل يجب على النساء ستر اليدين في الصلاة؟","title":"حكم ستر المرأة يديها في الصلاة","answer":"الجواب:  الستر أفضل، ولا حرج في كشفهما، الوجه يكشف في الصلاة إذا كان ما عندها أجانب، ما عندها رجل ليس بمحرم، وهكذا الكفان، وإن سترتهما فلا بأس، الأمر واسع في الكفين، لكن الوجه السنة كشفه، إلا إذا كان هناك أجنبي، أما اليدان يعني: الكفين فهي مخيرة، إن سترتهما فهو أفضل وإن كشفتهما فلا حرج، نعم، أما القدمان فتسترهما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9201/حكم-ستر-المراة-يديها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36702.mp3","categories":["ستر العورة للمصلي"]},{"id":11399,"question":"إحدى الأخوات تسأل سماحتكم وتقول: أود أن أسأل عن انكشاف القدمين للمرأة أثناء الصلاة، هل يؤثر ذلك على الصلاة؟ وصاحبة هذا السؤال هي الأخت: (م. م. أ) من المنطقة الشرقية.","title":"حكم انكشاف قدم المرأة أثناء الصلاة","answer":"الجواب: إذا كان الانكشاف قليلًا؛ لا يؤثر وسترته، أما إذا استمر كثيرًا؛ تعيد الصلاة عند أكثر أهل العلم، أما إذا انكشف قليلًا، وسترته؛ فلا يضر إن شاء الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9602/حكم-انكشاف-قدم-المراة-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38020.mp3","categories":["ستر العورة للمصلي"]},{"id":11400,"question":"إحدى الأخوات تسأل وتقول: أرجو من سماحتكم إفادتنا، هل يجوز لبس الشرشف للصلاة وهو خفيف؟","title":"حكم لبس المرأة الشرشف في الصلاة","answer":"الجواب:  إذا كانت مستورة بغيره إذا كانت قد سترت بدنها بغير الشرشف؛ فهذا لا بأس، أما إذا كان الشرشف يستر أقدامها، يستر رأسها؛ فلابد أن يكون صفيقًا، ويستر، أما إذا كان الرأس مستورًا، والقدمان مستورتان، وهذا زود لا يضر، الحمد لله. وأما إذا كان لا، يحتاج إليه في ستر الرأس، وستر القدمين، فهذا لابد أن يكون صفيقًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9593/حكم-لبس-المراة-الشرشف-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38012.mp3","categories":["ستر العورة للمصلي"]},{"id":11402,"question":"هذه سائلة من العراق تقول في هذا  أسأل وأقول: ما الحكمة لارتداء المسلمة الحجاب أثناء الصلاة، هل هو من أجل حضور الملائكة أثناء الصلاة؛ أم لأنها تقف بين يدي الله ؟ لأن ابنتي سألتني هذا السؤال، ولا أعرف الإجابة الصحيحة، فسألتكم مأجورين.","title":"الحكمة من ارتداء المرأة حجابها أثناء الصلاة","answer":"الجواب:  ليس عليها حجاب إذا كانت تصلي، وليس عندها رجال أجانب، لها أن تكشف وجهها، أما كونها تستر رأسها وبدنها فهذا؛ لأنها عورة، فوقوفها بين يدي الله مستورة أفضل. ولأنه قد يبدو من ليس محرمًا لها، قد يدخل المحل من ليس محرمًا لها، فقد تعمل بالحيطة إلا الوجه فإنها تكشفه إذا كان ما عندها أجنبي، وتستر بقية بدنها، هذا هو المشروع، هذا هو الواجب عليها، إلا الكفين فلا مانع من كشفهما وسترهما أفضل، أما الوجه فالسنة كشفه في الصلاة، إذا كان ما عندها أجنبي، وأما إذا كان عندها أجنبي فإنها تستره؛ لأنها عورة وفتنة، نعم.","link":"https://binbaz.org.sa/fatwas/9584/الحكمة-من-ارتداء-المراة-حجابها-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29318.mp3","categories":["ستر العورة للمصلي"]},{"id":11413,"question":"ما حكم ظهور يد المرأة أثناء الصلاة، أو الكف من غير قصد؟","title":"حكم ظهور يد المرأة في الصلاة دون قصد","answer":"الجواب:  الصواب لا حرج في ذلك، إن سترتهما؛ فأفضل، وإلا فلا حرج، أما الوجه فكشفه أفضل في الصلاة، إلا إذا كان عندها أجنبي؛ تستره، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9594/حكم-ظهور-يد-المراة-في-الصلاة-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38013.mp3","categories":["ستر العورة للمصلي"]},{"id":11414,"question":"إذا ظهر شعر المرأة في الصلاة قليلًا من المقدمة، أو من الجانبين، هل الصلاة صحيحة؟ وهل إذا علمت من إحدى أخواتها ماذا تفعل؟ جزاكم الله خيرًا.","title":"حكم ظهور شعر المرأة في الصلاة دون قصد","answer":"الجواب:  إن استمر؛ تعيد الصلاة، وإن كان قليلًا تفطنت وغطته فالحمد لله يعفى عن ذلك، إن شاء الله. المقدم: بارك الله فيكم.  السؤال: تقول: إذا أخبرتها إحدى أخواتها أثناء الصلاة؟ الشيخ: تستره والحمد لله. المقدم: وحينئذ الصلاة صحيحة؟ الشيخ: إيه نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9595/حكم-ظهور-شعر-المراة-في-الصلاة-دون-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38014.mp3","categories":["ستر العورة للمصلي"]},{"id":11734,"question":"ما هو الحجاب الشرعي للمرأة؟ وهل كشف الوجه والكفين جائز، أو لا؟","title":"حد عورة المرأة عند الأجانب وعند النساء وفي الصلاة","answer":"الجواب: المرأة عورة كلها عند الأجنبي تستر بدنها كله الوجه والكفين، وغير ذلك عورة، لكن في بيتها، وعند النساء لا بأس أن تكشف وجهها ويديها ورأسها، أو رجلها، لا بأس عند النساء، وفي الصلاة تكشف وجهها، السنة كشف الوجه في الصلاة، وهي تصلي إذا ما كان عندها أجنبي، وأما اليدان فالأفضل سترهما، وإن كشفت صحت الصلاة، لكن الأفضل سترهما؛ خروجًا من الخلاف، أما القدمان فالواجب سترهما عند أكثر أهل العلم في الصلاة، لكن إذا كان يراها أجنبي؛ وجب أن تستر وجهها، وجميع بدنها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9920/حد-عورة-المراة-عند-الاجانب-وعند-النساء-وفي-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39305.mp3","categories":["ستر العورة للمصلي"]},{"id":11768,"question":"هل تجوز الصلاة في ثياب لا تصل إلا إلى الركبتين؟","title":"حكم الصلاة في ثوب يصل إلى الركبتين","answer":"الجواب:  في حق الرجل لا بأس، أما المرأة لا، لابد أن تستر بدنها كله، إلا الوجه، أما الرجل فلا بأس، إذا ستر ما بين السرة والركبة، وستر العاتقين؛ فلا بأس، يكون رأسه مكشوفًا، الساق .... لا حرج، لكن كونه في زينته المناسبة، وفي عادته المناسبة يكون أفضل؛ لأن الله سبحانه يقول: خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31] يعني: عند كل صلاة، فكون المؤمن يصلي في حالة حسنة كاملة، هذا أطيب وأفضل، وإلا فيجزيه لو بدا ساقاه، أو كشف رأسه، لا حرج في ذلك، لكن يستر العاتقين، لقوله ﷺ: لا يصلي أحدكم في الثوب الواحد ليس على عاتقيه منه شيء في لفظ: ليس على عاتقه منه شيء.  أما المرأة فهي عورة كلها، تستر بدنها كله، ورأسها إلا وجهها، إلا إذا كان عندها أجنبي؛ تستر وجهها أيضًا، وإن أبدت الكفين؛ فلا حرج، لكن سترهما أولى؛ خروجًا من الخلاف. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9952/حكم-الصلاة-في-ثوب-يصل-الى-الركبتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39414.mp3","categories":["ستر العورة للمصلي"]},{"id":11850,"question":"من المنطقة الشرقية رسالة بتوقيع إحدى الأخوات المستمعات، تقول أم حنان، أم حنان تقول: قرأت في إحدى الكتيبات بأن حجاب المرأة ليس شرطًا أن يكون عباءة، أو كابًا، بل المهم أن تتوفر فيه شروط الحجاب الشرعي، وأنا ولله الحمد امرأة ملتزمة، وحجابي عبارة عن كاب واسع جدًا، وطرحة طويلة وكثيفة، وغطاء للوجه، وقفازات وجوارب، ولكن يا سماحة الشيخ! قرأت مرة أخرى فتوى: بأنه لا يجوز أن يكون الحجاب على الكتف كما هو الحال في الكاب، فهل لبسي للكاب حرام؟ علمًا بأنه واسع، وغير ملفت للنظر، وشكلي العام محتشم، ولله الحمد.","title":"صفة حجاب المرأة في الصلاة وخارجها","answer":"الجواب:  الواجب في الحجاب أن تصلي المرأة مستورة ما عدا الوجه والكفين، الوجه السنة أن يكون مكشوفًا، والكفان سترهما أفضل وأحوط، وأما البقية يجب أن يستر في الصلاة، أما في غير الصلاة فإنها تحتجب عن الرجال، وتلبس لباسًا ليس فيه تشبه بالكفرة، وليس فيه تشبه بالرجال، تكون ملابسها ساترة حاجبة لها عن الرجال، لكن لا يكون فيها مشابهة للكفرة للنساء الكفرة، ولا مشابهة للرجال. فالكابل إذا كان ليس فيه تشبه بالكفرة وليس فيه تشبه بالنساء وهو ساتر؛ فلا بأس، إذا كان ليس فيه تشبه بالكافرات، وليس فيه تشبه بالرجال، وهو يستر؛ فلا بأس، تحرى المرأة اللباس الذي لا تشابه به نساء الكفرة، ولا تشابه به الرجال. نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ! المعروف عن هذا الكاب أنه قد يصف تقاطيع جسم المرأة؟ الشيخ: إذا كان ضيقًا لا يصلى فيه، لكن إذا كان ساترًا واسعًا، وليس فيه تشبه بالكافرات، ولا بالرجال؛ فلا بأس. المقدم: جزاكم الله خيرًا، هذا من حيث الصلاة، لكن من حيث الخروج به إلى الشارع. الشيخ: مثلما تقدم إذا كان يسترها، وليس فيه تشبه لا بأس. المقدم: هو يسترها، لكنه يصف أعضاء جسمها. الشيخ: لا ... إذا كان يصف لا .... تلبس شيئًا لا يصف الأعضاء، عباءة وغيرها. نعم. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10026/صفة-حجاب-المراة-في-الصلاة-وخارجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39606.mp3","categories":["ستر العورة للمصلي"]},{"id":11863,"question":"المستمع أحمد شعبان يسأل ويقول: هل تغطية اليدين والقدمين بالنسبة للمرأة في الصلاة واجبة؟ أو بماذا توجهون الناس؟ جزاكم الله خيرًا.","title":"حكم تغطية المرأة قدميها ويديها في الصلاة","answer":"الجواب:  السنة للمرأة كشف الوجه في الصلاة، إذا لم يكن عندها أجنبي غير محرم، هذا هو السنة تكشف وجهها، تسجد مكشوفة الوجه، وهكذا في حال القيام، وأما القدمان وسائر البدن فيكون مستورًا، الواجب عليها ستر جميع البدن، ما عدا الوجه والكفين، أما الوجه فكشفه سنة، إلا إذا كان عندها غير محرم، أما الكفان فإن سترتهما؛ فهو أفضل، وإن كشفتهما؛ فلا حرج على الصحيح، وبعض أهل العلم يرى وجوب ستر الكفين، فإن سترتهما فهو أفضل؛ خروجًا من الخلاف، وإن كشفت الكفين في الصلاة؛ فالصواب أنها صحيحة الصلاة، لكن سترهما أفضل خروجًا من الخلاف. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10044/حكم-تغطية-المراة-قدميها-ويديها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_397/39707.mp3","categories":["ستر العورة للمصلي"]},{"id":11992,"question":"بعد هذا ننتقل إلى رسالة بعثت بها إحدى الأخوات، تقول: سرام سيف المطيري من قرية أم أرطى، أختنا تسأل جمعًا من الأسئلة، فتقول: هل ظهور الشعر في الصلاة يبطلها بالنسبة للمرأة؟","title":"ظهور شعر المرأة في الصلاة","answer":"الجواب:  نعم، لابد من التستر، يقول ﷺ: لا يقبل الله صلاة حائض إلا بخمار لابد تستر شعرها. لكن لو ظهر الشيء اليسير ثم غطته في الحال لا يضر -إن شاء الله- عليها أن تلاحظ وتعتني،  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10177/ظهور-شعر-المراة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43106.mp3","categories":["ستر العورة للمصلي"]},{"id":12098,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع (م . م . م) من الرياض، أخونا عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة يسأل سماحتكم شيخ عبدالعزيز، فيقول: إذا كنت أصلي، وبعد انتهائي من الصلاة، صلاة الظهر مثلًا، اكتشفت أن جزءًا من شعري ظاهر -يبدو أن هذا السؤال لامرأة سماحة الشيخ- فهل أعيد الصلاة، أم أعيد الركعتين الأخيرتين التي اكتشفت أن شعري كان مكشوفًا خلالهما؟ جزاكم الله خيرًا.","title":"حكم من صلت وجزء من شعرها كان مكشوفاً","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن هذا الموضوع فيه تفصيل: فإن كان المنكشف شيئًا قليلًا، ولم تشعري به إلا بعد الصلاة؛ فلا حرج عليك، والصلاة صحيحة، أما إذا كان المكشوف شيئًا كثيرًا؛ فالأحوط لك الإعادة، نعم.","link":"https://binbaz.org.sa/fatwas/10283/حكم-من-صلت-وجزء-من-شعرها-كان-مكشوفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_437/43701.mp3","categories":["ستر العورة للمصلي"]},{"id":12348,"question":"هل تصح الصلاة في سروال قصير من فوق الركبة؛ لأنني قرأت في إحدى الصحف فتوى لعالم من مصر يجوز الصلاة في هذا السروال القصير عندما سأله أحد الناس عن ذلك، وأنا قد سمعت أيضًا بأن ذلك لا يجوز، فعلى أي القولين نسير؟ جزاكم الله خيرًا.","title":"حكم الصلاة بالسراويل القصيرة","answer":"الجواب: الصواب أنه لا يصح، وأن الواجب ستر ما بين السرة والركبة، وأن الفخذ عورة، فلا يجوز للمسلم أن يصلي مكشوف الفخذ، بل يجب أن يستر الفخذ، وما تحت السرة، وإذا كان على كتفيه رداء يكون أكمل؛ لقوله ﷺ: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء. فينبغي أن يكون مع ذلك على عاتقه شيء رداء أو نحوه مع السراويل، أو مع الإزار، هكذا السنة، وذهب بعض أهل العلم إلى أنه إذا صلى، وليس على عاتقه شيء، لا تصح صلاته؛ لقوله ﷺ: لا يصلي أحدكم في الثوب الواحد ليس على عاتقه منه شيء. فالواجب على المسلم أن يتحرى السنة، وأن يحرص على امتثال أمر الرسول ﷺ فيستر ما بين السرة والركبة، ويجعل على عاتقه رداء أو فنيلة ساترة لمنكبيه حتى يجمع بين الأمرين اللذين أرشد إليهما النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10542/حكم-الصلاة-بالسراويل-القصيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45412.mp3","categories":["ستر العورة للمصلي"]},{"id":12394,"question":"كيف تؤدي المرأة صلاتها مع وجود رجال من غير المحارم، هل تؤديها واقفة، أم قاعدة؟","title":"صلاة المرأة أمام الرجال هل تؤديها واقفة؟","answer":"الجواب:  تؤديها واقفة مستورة، إن تيسر؛ فلا بأس، وإن تيسر مكانًا آخر تصلي فيه؛ فهو أحسن وأطيب وأخشع لها، وإن لم يتيسر؛ صلت في المكان، ولكن مع التستر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10594/صلاة-المراة-امام-الرجال-هل-توديها-واقفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40113.mp3","categories":["ستر العورة للمصلي","قضايا المرأة"]},{"id":12745,"question":"هل يجوز للمحرم أن يصلي مكشوف العاتقين؟","title":"حكم صلاة مكشوف العاتقين","answer":"الجواب:  ليس له ذلك، يقول النبي ﷺ: لا يصلين أحدكم في الثوب الواحد ليس على عاتقه منه شيء فالمحرم يصلي في ردائه، يجعل رداءه على كتفيه، ويصلي، ولا يصلي مكشوف العاتقين. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10959/حكم-صلاة-مكشوف-العاتقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41816.mp3","categories":["ستر العورة للمصلي"]},{"id":13052,"question":"سماحة الشيخ! هذه السائلة تقول: ما هو حد عورة المرأة مع المرأة، سواء كانت مسلمة، أو كتابية؟","title":"حد عورة المرأة بين مثيلاتها النساء","answer":"الجواب:  ما بين السرة والركبة، ما بين السرة والركبة عورة المرأة مع المرأة مطلقًا، كافرة أو مسلمة، نعم.","link":"https://binbaz.org.sa/fatwas/11269/حد-عورة-المراة-بين-مثيلاتها-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50512.mp3","categories":["ستر العورة للمصلي"]},{"id":13153,"question":"هل يجوز للمرأة أن تصلي بالنقاب، أو البرقع عندما تصلي، أم أنها تخلعه، وتضع شيئًا على وجهها كاملًا، وهي تصلي أمام الرجال؟","title":"تغطية المرأة وجهها في الصلاة أمام الرجال","answer":"الجواب:  الواجب عليها ستر وجهها بخمار، أو غيره، إذا كان عندها أجانب، أجنبي ليس محرمًا لها، تصلي مع ستر الوجه بخمار، أو نقاب، أو غيرهما، وأما إذا كان ما عندها أحد؛ فالسنة أن تكشف وجهها، نعم.","link":"https://binbaz.org.sa/fatwas/11407/تغطية-المراة-وجهها-في-الصلاة-امام-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51013.mp3","categories":["ستر العورة للمصلي"]},{"id":13289,"question":"بعد ذلك ننتقل إلى رسالة بعث بها السائل الذي رمز لاسمه بـ( ش. البراك ) من مدينة الجوف، يقول: ما حكم الصلاة في الثياب الخفيفة -أي: التي يظهر الجسم من خلالها- مثل: الثياب البيضاء، وهل الصلاة فيها مقبولة؟ أرجو توضيح الحكم في ذلك سماحة الشيخ.","title":"حكم لبس الثياب الشفافة في الصلاة","answer":"الجواب:  إذا كانت يرى منها اللحم ما تستر اللحم، ما بين السرة والركبة ما تصح الصلاة لخفتها ورقتها، أما إذا كانت خفيفة لكن تستر؛ فلا حرج، الصلاة صحيحة، لكن ينبغي للمؤمن أن يلبس لباسًا ساترًا، لا يبين حجم الأعضاء، ويستر العورة؛ حتى يكون لباسًا كاملًا، هذا هو الأكمل، والأحسن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11574/حكم-لبس-الثياب-الشفافة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_514/51414.mp3","categories":["ستر العورة للمصلي"]},{"id":13324,"question":"هذا السائل يقول: هل الركبة داخلة في العورة؟ أم ما فوقها داخل في العورة؟","title":"هل الركبة داخلة في العورة؟","answer":"الجواب: الركبة هي الفاصلة بين العورة وغير العورة، ما فوق الركبة من العورة، والركبة وما تحتها ليست من العورة في حق الرجل، أما المرأة كلها عورة، إلا وجهها في الصلاة، المرأة كلها عورة إلا وجهها في الصلاة، وإذا كان عندها أجنبي؛ سترت وجهها أيضًا، وفي الكفين خلاف هل تسترهما في الصلاة؟ أم لا؟ وسترهما أحوط، وأولى في الصلاة، أما الرجل فعورته ما بين الركبة والسرة، فالركبة ليست من العورة، بل هي تبع الساق، لكن ستر ذلك في الصلاة حتى في حق الرجل أولى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11610/هل-الركبة-داخلة-في-العورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54106.mp3","categories":["ستر العورة للمصلي"]},{"id":13397,"question":"ما حكم صلاة المرأة داخل بيتها وهي مكشوفة اليدين والقدمين، ولكن لا يراها أحد من الرجال؟","title":"حكم صلاة المرأة مكشوفة اليدين والقدمين","answer":"الجواب: المرأة عورة، كلها عورة، يجب أن تستر بدنها في الصلاة، ولو ما عندها أحد إلا الوجه؛ فالسنة كشفه، أما بقية بدنها فالمشروع ستره، بل يجب ستره إلا الكفين، بعض أهل العلم أجاز كشفهما، والأفضل سترهما، والأحوط سترهما، فإذا صلت وقدماها مكشوفتان، أو رأسها، أو ذراعها، أو صدرها؛ لم تصح صلاتها. فالواجب على المرأة أن تستتر إلا الوجه، وهكذا الكفان، الأحوط سترهما؛ لأنها عورة كلها، ولو ما حضرها أجنبي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11688/حكم-صلاة-المراة-مكشوفة-اليدين-والقدمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51602.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":13783,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع العوني أبو عونية أخونا عرضنا بعض أسئلته في حلقة مضت وفي هذه الحلقة يسأل ويقول: ما حكم الصلاة بالملابس الضيقة للرجال؟ وهل يصلي بالناس من يرتديها؟","title":"حكم الصلاة بالملابس الضيقة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالملابس الضيقة يكره لبسها للرجال والنساء جميعًا، والمشروع أن تكون الملابس متوسطة، لا ضيقة تبين حجم العورة ولا واسعة ولكن بين ذلك، أما الصلاة فهي صحيحة إذا كانت ساترة فالصلاة صحيحة، ولكن يكره للمؤمن تعاطي مثل هذه الألبسة الضيقة، وهكذا المؤمنة يكون اللباس متوسطًا بين الضيق والسعة، هذا هو الذي ينبغي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12138/حكم-الصلاة-بالملابس-الضيقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_601/60101.mp3","categories":["اللباس والزينة","ستر العورة للمصلي"]},{"id":13896,"question":"ما حكم لبس الثياب الضيقة التي تظهر أجزاء المرأة؟ وهل يجوز لها أن تصلي فيها أو لا؟","title":"حكم لبس المرأة الملابس الضيقة والصلاة فيها","answer":"الجواب: أقل أحوالها الكراهة، أقل أحوالها الكراهة، ما ينبغي أن تصلي في ثياب ضيقة، بل تكون وسط لا ضيقة ولا واسعة جدًا وسط، هذا السنة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12260/حكم-لبس-المراة-الملابس-الضيقة-والصلاة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48201.mp3","categories":["ستر العورة للمصلي","اللباس والزينة","قضايا المرأة"]},{"id":13951,"question":"يسأل ويقول: ما حكم صلاة المرأة في بيتها غير ساترة لرأسها أو رجليها، وليس عندها أحد؟","title":"حكم صلاة المرأة في بيتها غير ساترة لرأسها وقدميها","answer":"الجواب: ليس لها ذلك، يجب عليها ستر رأسها ورجليها على الصحيح، أما الوجه تكشفه السنة لها كشف الوجه، أما الكفان فالأفضل سترهما، وإن كشفتهما فالصحيح: أنه لا حرج؛ لأن بهما الأخذ والعطاء والتعديل، فالأمر في الكفين واسع وسترهما أفضل، أما الرجلان فالجمهور من أهل العلم على أنهما يستران، ينبغي سترهما كما قال الأكثر من أهل العلم، وجاء في حديث فيه لين عن أم سلمة أنها سئلت عن ذلك؟ -عن كشف القدمين- فقالت رضي الله عنها: \"إذا كان الدرع سابغًا يغطي ظهور قدميها\" -لما قيل لها-: \"يا أم المؤمنين هل تصلي المرأة في درع وخمار من غير إزار؟ قالت: إذا كان الدرع سابغًا يغطي ظهور قدميها\"، وفي إسناده بعض الضعف، ويروى مرفوعًا عن النبي ﷺ، لكن الصواب أنه موقوف.\nفالحاصل: أن سترها للقدمين أحوط للمؤمنة، وأما الكفان فأمرهما أوسع، وأما الوجه فيكشف في الصلاة إذا كان ما عندها أجنبي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12354/حكم-صلاة-المراة-في-بيتها-غير-ساترة-لراسها-وقدميها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48216.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":13975,"question":"المستمعة أم أحمد من المنطقة الشمالية رفحا، وتعمل معلمة، بعثت برسالة ضمنتها ثمانية أسئلة.في سؤالها الأول تقول: هل تغطية الرأس واليدين والقدمين واجبة عند سجود التلاوة؟","title":"حكم تغطية المرأة رأسها ويديها وقدميها لسجود التلاوة","answer":"الجواب: ليست واجبة لا، سجود التلاوة ليست صلاة، بل هي خضوع لله وذل بين يديه، كالقراءة والذكر ونحو ذلك، هذا هو الصواب، وقال بعض أهل العلم: إنها كالصلاة، لا بد من طهارة ولا بد من ستر عورة، فإذا سجدت المرأة بتستر؛ كان هذا أفضل وأولى خروجًا من خلاف العلماء، وهكذا إذا كانت على طهارة، كالرجل سواء، ولكن لا يجب هذا، لو سجدت ورأسها مكشوف، أو وهي على غير وضوء؛ فالسجود صحيح على الصحيح، ولا حرج في ذلك، كالرجل، فإن سجود التلاوة يمر على الإنسان وهو يقرأ القرآن عن ظهر قلب وهو على غير طهارة.\nولم يثبت عن النبي ﷺ أنه أمر بذلك، وقد ثبت عن ابن عمر  ما يدل على أنه ليس بشرط، وأنه لا مانع من السجود على غير طهارة.\nفالحاصل: أن سجود التلاوة وسجود الشكر لا يشترط لهما الطهارة، فلو بشر بولد له أو بفتح إسلامي، أو بأمر يسر ينفع المسلمين؛ فسجد شكراً لله، فلا بأس ولو كان على غير طهارة، ولما بلغ الصديق  مقتل مسيلمة الكذاب سجد لله شكرا.\nفالحاصل: أن سجود التلاوة وسجود الشكر لا يشترط لهما الطهارة، ولا السترة التي تشترط في الصلاة، بل الأمر فيهما أوسع والحمد لله، هذا هو الصواب.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12420/حكم-تغطية-المراة-راسها-ويديها-وقدميها-لسجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60608.mp3","categories":["سجود التلاوة والشكر","ستر العورة للمصلي","قضايا المرأة"]},{"id":14756,"question":"هل الصلاة والرجل بدون غطاء كالجوارب مثلًا باطلة؟ أفيدوني، جزاكم الله خيرًا.","title":"ما حكم صلاة المرأة وقدمها مكشوفة؟","answer":"الجواب: نعم، عند جمهور أهل العلم أن انكشاف رجلي المرأة يبطل الصلاة.  فالواجب سترهما، إما بإسباغ الثياب تكون طويلة، أو بلباس الجوربين، هذا هو الذي عليه جمهور أهل العلم، والأصل في هذا حديث أم سلمة مرفوعًا وموقوفًا أنها سئلت «أتصلي المرأة في درع وخمار؟ فقالت -رضي الله عنها-: نعم إذا كان الدرع سابغًا يغطي ظهور قدميها» روي مرفوعًا إلى النبي ﷺ وموقوفًا عليها، وصححه الأئمة أئمة الحديث، وقفوه على أم سلمة -رضي الله عنها-؛ ولأن المرأة عورة كما في الحديث: المرأة عورة فالرجل من العورة، فالواجب سترها، إما بإسباغ الثياب، وطول الثياب، وإما بالجوربين، بالجوارب التي تستر القدمين. وأما الرجل معلوم أنه عورته ما بين السرة والركبة في الصلاة. وأما الكفان للمرأة فسترهما أولى، وإن كشفتهما مع الوجه فلا بأس في الصلاة إذا كان ما عندها أجنبي، وأما الوجه فالأفضل كشفه، إذا كان ما عندها أجنبي السنة كشف وجهها، وأن تصلي مكشوفة الوجه إذا كانت في محلها ليس عندها أجانب، وأما الكفان فهي مخيرة إن سترتهما فهو أفضل، وإن كشفتهما فلا حرج -إن شاء الله-، وأما الرجلان فالواجب سترهما كما تقدم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13267/ما-حكم-صلاة-المراة-وقدمها-مكشوفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63805.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":14794,"question":"من ليبيا هذا السائل: عمر من طرابلس يقول في هذا  هل يجوز للمرأة أن تصلي والقدمان مكشوفتان سماحة الشيخ؟","title":"حكم ستر المرأة قدميها في الصلاة","answer":"الجواب: الواجب عليها ستر القدمين عند جمهور أهل العلم، الواجب عليها ستر القدمين، وقد جاء في حديث أم سلمة «أنها سئلت عن المرأة تصلي في درع وخمار، فقالت: إذا كان الدرع سابغًا، يغطي ظهور قدميها» تصلي في درع سابغ يستر أقدامها، أو تكون في أقدامها الجوارب، هذا هو المشروع عند جمهور أهل العلم، يجب عليها ستر القدمين، إما بكون الثياب ضافية، أو باتخاذ جوارب في الرجلين، هذا هو المشروع لها، وهو الواجب عند جمهور أهل العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13286/حكم-ستر-المراة-قدميها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56117.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":15166,"question":"أيضًا تقول: ما حكم لبس البنطلون للطبيب وما حكم الصلاة به؟","title":"حكم الصلاة بالبنطلون","answer":"الجواب: إذا كان البنطلون ساترًا للعورة، غير مميز لها، بل هو واسع وضافي؛ فإنه تصح به الصلاة إذا كان على كتفيه شيء، إذا كان السترة والبنطلون كافيان، يعني: البنطلون معه السترة التي على كتفيه وصدره ونحوه.  المقصود: إذا كان العورة مستورة ما بين الركبة والسرة، وكان على العاتقين شيء أو أحدهما؛ فإنه يجزئ. أما إذا كان ضيقًا، يبين حجم العورة، فلا ينبغي استعماله -الله المستعان- والنبي  قال: لا يصل أحدكم في الثوب الواحد ليس على عاتقه منه شيء فإذا كان عنده قدرة وجب أن يستر العورة، ويضع على الكتفين شيئًا من الرداء، أو على أحدهما، نعم.","link":"https://binbaz.org.sa/fatwas/13683/حكم-الصلاة-بالبنطلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65911.mp3","categories":["ستر العورة للمصلي"]},{"id":15173,"question":"أيضًا تقول: ما حكم لبس البنطلون للطبيب وما حكم الصلاة به؟","title":"حكم الصلاة بالبنطلون","answer":"الجواب: إذا كان البنطلون ساترًا للعورة، غير مميز لها، بل هو واسع وضافي؛ فإنه تصح به الصلاة إذا كان على كتفيه شيء، إذا كان السترة والبنطلون كافيان، يعني: البنطلون معه السترة التي على كتفيه وصدره ونحوه.  المقصود: إذا كان العورة مستورة ما بين الركبة والسرة، وكان على العاتقين شيء أو أحدهما؛ فإنه يجزئ. أما إذا كان ضيقًا، يبين حجم العورة، فلا ينبغي استعماله -الله المستعان- والنبي  قال: لا يصل أحدكم في الثوب الواحد ليس على عاتقه منه شيء فإذا كان عنده قدرة وجب أن يستر العورة، ويضع على الكتفين شيئًا من الرداء، أو على أحدهما، نعم.","link":"https://binbaz.org.sa/fatwas/13683/حكم-الصلاة-بالبنطلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65911.mp3","categories":["ستر العورة للمصلي"]},{"id":15360,"question":"تسأل هذه السائلة من سوريا، أم عبدالرحمن عن الحجاب الشرعي بالنسبة للمرأة في الصلاة، وفي غير الصلاة؟","title":"صفة حجاب المرأة في الصلاة وخارجها","answer":"الجواب: أما في الصلاة فتستر جميع بدنها، إلا الوجه هذا هو الأفضل، إذا كان ما عندها أجانب تبدي الوجه، السنة كشف الوجه في الصلاة، وتستر جميع بدنها، حتى الكفين، وإن أبدت الكفين فلا حرج، يعني سترهما أفضل في الصلاة، أما إذا كان عندها أجنبي، فإنها تستر بدنها كله، حتى الوجه.  وأما عند الناس عند الأجانب، وفي الأسواق، وفي البيوت، فإنها تكشف ما شاءت من بدنها، كالرأس والوجه واليدين والقدمين، ما دام ما عندها أجانب في بيتها في فراشها في أي مكان من بيتها، أما عند الأجنبي فهي عورة تستر جميع بدنها؛ لأنها عورة، الله يقول -جل وعلا-: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ويقول -جل وعلا-: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ [الأحزاب:59] الآية، والجلباب: ما تغطي به المرأة رأسها ووجهها وبدنها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13863/صفة-حجاب-المراة-في-الصلاة-وخارجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49903.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":15402,"question":"هذا سائل للبرنامج يقول: هل يجوز للمرأة أن تصلي داخل بيتها دون أن ترتدي الجوارب لتستر القدمين؟ وهل إذا نسيت ذلك هل تبطل الصلاة؟","title":"حكم تغطية المرأة قدميها في الصلاة","answer":"الجواب: الواجب عليها ستر قدميها بالجوارب، أو بالثياب الطويلة، فإذا صلت وثيابها طويلة تكفي، إذا كانت تغطي قدميها، ما يلزم جوارب، وإذا كانت قصيرة تلبس الجوارب، نعم.","link":"https://binbaz.org.sa/fatwas/13900/حكم-تغطية-المراة-قدميها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56721.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":15542,"question":"هذه السائلة تقول: سماحة الشيخ، هل تغطية الرأس من سنن العبادة؟","title":"حكم تغطية الرأس في الصلاة وغيرها","answer":"الجواب: تغطية الرأس إذا كان في الصلاة أفضل، من الزينة؛ لأن الله قال -جل وعلا-: خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ [الأعراف:31] يعني: عند كل صلاة، وإن كشف فلا حرج، ليس بعورة. أما المرأة لا،ـ عليها أن تغطي رأسها في الصلاة، ولا يجوز لها كشفه؛ لأنه عورة بالنسبة إليها، أما في بيتها من غير صلاة إن كشفت رأسها ما عندها إلا النساء، أو ما عندها أحد، ولو أنها تقرأ لا حرج، لا حرج في كشف الرأس للمرأة التي ما عندها أجنبي، ولو كان عندها بعض النساء، ولو كان عندها زوجها وبعض محارمها، ولو كانت تقرأ لا حرج في ذلك، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14076/حكم-تغطية-الراس-في-الصلاة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56927.mp3","categories":["ستر العورة للمصلي"]},{"id":15788,"question":"ما حكم أن تخرج المرأة وقدمها مكشوفة، أو كذلك تكون قدمها مكشوفة عند الصلاة؟","title":"حكم ستر المرأة قدميها في الصلاة وخارجها","answer":"الجواب: لا تخرج إلى الناس وقدماها مشكوفتان، بل تسترهما بالملابس الضافية، أو بالجوربين، وهكذا في الصلاة تكون مستورة القدمين عند جمهور أهل العلم، يجب سترهما في الصلاة بالملابس الضافية الطويلة أو بالجوربين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14378/حكم-ستر-المراة-قدميها-في-الصلاة-وخارجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74215.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":15835,"question":"هل تجوز الصلاة والقدمان مكشوفتان بالنسبة للنساء؟","title":"ما حكم صلاة المرأة وقدماها مكشوفتان؟","answer":"الجواب: الواجب ستر القدمين عند جمهور أهل العلم، الواجب ستر القدمين في الصلاة للمرأة. نعم.","link":"https://binbaz.org.sa/fatwas/14426/ما-حكم-صلاة-المراة-وقدماها-مكشوفتان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/57527.mp3","categories":["ستر العورة للمصلي"]},{"id":16106,"question":"تقول السائلة -يا سماحة الشيخ- أم محمد: صليت صلاة الظهر، وعند سجودي كشف ابني الغطاء عن جميع رأسي، وذلك بسحب الشرشف الذي أصلي فيه، وأخذت الشرشف بسرعة على رأسي، وأكملت الصلاة، فهل صلاتي صحيحة؟","title":"حكم صلاة من انكشف رأسها ثم غطته","answer":"الجواب: نعم إذا أخذت السترة بسرعة لا بأس الصلاة صحيحة، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/14754/حكم-صلاة-من-انكشف-راسها-ثم-غطته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_579/57925.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":16344,"question":"إذا صليت وأقدامي مكشوفة، فما الحكم؟","title":"حكم ستر المرأة أقدامها في الصلاة","answer":"الجواب: ستر الأقدام واجب، وشرط من شروط الصلاة عند جمهور العلماء، فإذا صليت والقدمان مكشوفتان؛ فعليك الإعادة، فعليك أن تستري القدمين بالجوارب، أو بالثياب الطويلة، وفقنا الله وإياك للخير. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15038/حكم-ستر-المراة-اقدامها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71407.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17204,"question":"تقول السائلة أيضًا من ضمن أسئلتها: بالنسبة لإظهار القدمين أثناء الصلاة بالنسبة للمرأة؟","title":"الواجب على المرأة ستر القدمين أثناء الصلاة","answer":"الجواب: الواجب ستر القدمين، عند أكثر أهل العلم، الواجب عليها أن تستر قدميها بملابسها. نعم.","link":"https://binbaz.org.sa/fatwas/16026/الواجب-على-المراة-ستر-القدمين-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59032.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17211,"question":"إحدى الأخوات المستمعات تسأل سماحتكم شيخ عبد العزيز عن حكم لبس الشراب من أجل الصلاة؟","title":"ما حكم لبس المرأة للشراب في الصلاة؟","answer":"الجواب: طيب، إذا لبست الشراب حتى تستر قدميها، كله طيب، أو كانت الثياب طويلة تغطي الأقدام فلا بأس كله طيب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16037/ما-حكم-لبس-المراة-للشراب-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72307.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17212,"question":"تسأل سماحتكم أيضًا عن حكم تغطية اليدين في الصلاة؟","title":"حكم تغطية المرأة ليديها في الصلاة","answer":"الجواب: إن غطت هذا أفضل، وإلا فليس بلازم، فالكشف لا بأس به، والوجه يشرع كشفه في الصلاة، المرأة تكشف وجهها في الصلاة، إلا إذا كان عندها أجنبي فإنها تغطي وجهها، أما إذا كان ما عندها إلا زوجها، أو نساء فالسنة أن يكون الوجه مكشوفًا، أما اليدان فإن شاءت كشفتهما على الصحيح، وإن شاءت سترتهما، وهو أفضل، خروجًا من خلاف من قال بوجوب سترهما، أما القدمان فيسترا. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16038/حكم-تغطية-المراة-ليديها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72308.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17277,"question":"نعرض لأختنا آخر سؤال لها فتقول: هل يجوز للمرأة الصلاة خارج البيت، وأمام بعض الأقارب، علمًا بأننا في الريف، ولا يوجد لنا بيت، ولبسي محتشم، والحمد لله؟","title":"حكم صلاة المرأة خارج البيت","answer":"الجواب: لا حرج في ذلك أن تصلي في الريف .. في الخيام .. في الصحراء متسترة، ولو رآها الناس، ما دامت متسترة، فالحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16124/حكم-صلاة-المراة-خارج-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76814.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17747,"question":"السائلة: زهراء علي تقول سماحة الشيخ: ما هي حدود عورة المرأة مع المرأة؟","title":"حدود عورة المرأة مع المرأة","answer":"الجواب: ما بين السرة والركبة هذه العورة المستفحشة، ولكن ينبغي لها أن تحتشم، تلبس الثياب الضافية، تستر بدنها كله، تكون قدوة في الخير، تستر بدنها ورأسها، تكون قدوة في الخير، لكن لو رأت المرأة منها صدرها، أو رأت رأسها، أو رأت ذراعها لا يضر، أو رأت ساقها لا يضر، لكن كونها تحتشم.. تلبس الملابس الحشيمة الطيبة، هذا هو الأولى والأحوط. نعم.","link":"https://binbaz.org.sa/fatwas/16712/حدود-عورة-المراة-مع-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59609.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17850,"question":"تلبس المرأة غطاءً ساترًا أثناء تأدية الصلاة، وهي داخلة بيتها، فهل يجوز لها لبس هذا الغطاء؛ حتى وإن كانت لوحدها؟ رغم أنه يستر جميع البدن، أم أنه لابد لها من لبس شيءٍ على رأسها؟ وعلى شعرها؟ بالرغم من وجود هذا الغطاء على جميع بدنها، جزاكم الله خيرًا.","title":"ما يشرع للمرأة كشفه في الصلاة","answer":"الجواب: إذا كان عليها غطاء يستر جميع بدنها؛ كفى، والحمد لله، ما عدا الوجه، فإن السنة كشفه، إن لم يكن عندها أجنبي فالسنة كشفه.\nأما الكفان؛ فإن كشفتهما، فلا حرج، وإن سترتهما فهو أفضل، أما بقية البدن من الرأس، والصدر، والقدم، وغير ذلك؛ تستر، سواءٌ كان بغطاءٍ عام، أو بغطاءٍ مقطع، للرأس ستر، ولبقية البدن ستر، فالمقصود أن تستر هذا البدن كله، ما عدا الوجه والكفين، الوجه سنة كشفه، والكفان سترهما أفضل، وإن كشفا؛ فلا حرج على الصحيح. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم، لباس المرأة العادي لا يكفيها أثناء تأدية صلاتها -سماحة الشيخ-؟\nالشيخ: العادي الساتر يكفيها، إذا كان ساترًا، فإنه يكفيها، إن كان عليها غطاءٌ للرأس -خمار ساتر- وعليها مدرعة ساترة لقدميها، أو في قدميها دسوس، يعني: جوارب، كفى والحمد لله.\nالمقدم: الحمد لله، جزاكم الله خيرًا، إذًا لا يلزم أن يكون هناك .......؟\nالشيخ: ما هو بلازم، ليس بلازم. نعم.\nالمقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16843/ما-يشرع-للمراة-كشفه-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72804.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17924,"question":"الأخت السائلة تقول: هل علي إثم إذا لبست ملابس بدون أكمام أمام النساء وأمام والدي وإخوتي؟","title":"حكم ظهور ذراعي المرأة أمام النساء والمحارم","answer":"الجواب: الأقرب -والله أعلم- أنه لا إثم في ذلك؛ لأن الذراعين ليس بعورة، لكن الأفضل الحشمة والتستر، هذا أفضل وأبعد عن الشر، وإلا فلا إثم في ظهور الذراع للأب أو الأخ أو للنساء، أو الساق، لكن كونها تحتشم وتكون أكمامها ساترة وقميصها ساتر، كل هذا أكمل وأفضل.","link":"https://binbaz.org.sa/fatwas/16941/حكم-ظهور-ذراعي-المراة-امام-النساء-والمحارم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59824.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17932,"question":"هل الصلاة بدون جوارب غير جائزة، وهل ستر القدمين واجبة في الصلاة أو لا؟","title":"حكم ستر المرأة لقدميها في الصلاة","answer":"الجواب: المشروع سترهما بالجوربين أو بإرخاء الثياب، إذا أرخت الثياب حصل المقصود ولو ما كان هناك جوربان؛ لأنه جاء في حديث رواه أبو داود عن أم سلمة أنها سئلت رضي الله عنها : أتصلي المرأة في درع وخمار بغير إزار؟ فقالت: \"إذا كان الدرع سابغًا يغطي ظهور قدميها\".  والجمهور على أن القدمين عورة، وأن الواجب عليها سترهما في الصلاة، فينبغي للمؤمنة ستر القدمين بالجوارب أو بإرخاء الثياب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16979/حكم-ستر-المراة-لقدميها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_847/nour_84716.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":17949,"question":"سماحة الشيخ! هذه رسالة وصلت من المنطقة الشرقية من الأخت المستمعة (م. ص. س) تقول سماحة الشيخ: قراءة القرآن للمرأة هل يلزمها حجاب أم لا؟ وإذا مرت بآية سجدة هل تتحجب؟","title":"هل يلزم الحجاب لقراءة القرآن وسجود التلاوة؟","answer":"الجواب: لا يلزمها حجاب، إذا كان ما عندها أجنبي لا، ولو طرحت خمارها عن رأسها تقرأ لا بأس، إذا كان ما عندها أجنبي، وتسجد إذا مرت بسجود تلاوة تسجد، هذا هو الأفضل، وإذا كان مرت بآية سجود كونها تجعل الخمار على رأسها أفضل عند السجود. نعم.","link":"https://binbaz.org.sa/fatwas/16954/هل-يلزم-الحجاب-لقراءة-القران-وسجود-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59828.mp3","categories":["سجود التلاوة والشكر","ستر العورة للمصلي","قضايا المرأة"]},{"id":18035,"question":"آخر أسئلة أختنا من السودان: حكم الصلاة والمرأة تلبس القفازين؟","title":"حكم لبس المرأة القفازين في الصلاة","answer":"الجواب: لا مانع، تصلي في القفازين، وهذا أفضل لها ستر يديها في الصلاة بقفازين، أو بجلبابها الذي عليها، أو بغير ذلك هذا أفضل، ولا يبقى مكشوفًا إلا الوجه، هذا أفضل، وإن كشفت الكفين صح ذلك في أصح قولي العلماء. وهذا كله إذا كانت في محل ليس فيه أجنبي، أما إذا كان فيه رجل ليس محرمًا لها؛ فإنها تغطي جميع بدنها، حتى الوجه وهي في الصلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17065/حكم-لبس-المراة-القفازين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59911.mp3","categories":["قضايا المرأة","ستر العورة للمصلي"]},{"id":18349,"question":"أولى رسائل هذه الحلقة رسالة من إحدى الأخوات المستمعات بعثت بها وضمنتها عددًا من الأسئلة، هي ثلاثة عشر سؤالًا عرضنا جزءًا كبيرًا من أسئلتها في حلقات مضت، وفي هذه الحلقة تسأل عما يلي:أولًا: لقد سمعت بأن عورة الرجل هي في الصلاة فقط فهل هذا صحيح؟ أفيدونا جزاكم الله خيرًا؛ لأنا نشاهد المصارعة الحرة، والمصارعة كما تعلمون يرتدي أصحابها ملابس قصيرة جدًا، وجهونا جزاكم الله خيرًا.","title":"حدود عورة الرجل في الصلاة وغيرها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن عورة الرجل ما بين السرة والركبة، في الصلاة وخارجها، لكن يزاد على ذلك في الصلاة أن يستر عاتقيه أو أحدهما برداء ونحوه مع القدرة على ذلك، ولا يجوز للمؤمن في الصلاة أن يبدي شيئًا مما بين السرة والركبة، هذا هو الذي عليه جمهور أهل العلم، وهو الصواب. وذهب بعض أهل العلم إلى أن الفخذ ليس بعورة، ولكنه قول مرجوح، والصواب الذي دلت عليه الأحاديث عن رسول الله عليه الصلاة والسلام أنه عورة، وأن العورة ما بين السرة والركبة، هذا في جميع الأوقات، لكن في الصلاة يشرع له أن يضع على عاتقيه شيء كالرداء، وإن كان الإزار واسعًا التحف بأطرافه على عاتقيه وكفى؛ لقول النبي ﷺ لبعض الصحابة: من كان ثوبه واسعًا فالتحف به، وفي اللفظ الآخر: فخالف بين طرفيه، يعني: على عاتقيه، وإن كان ضيقًا فاتزر به ولقوله ﷺ: لا يصل أحدكم في الثوب الواحد ليس على عاتقه منه شيء، وفي اللفظ الآخر: ليس على عاتقيه منه شيء. وما يفعل في بعض الأحوال من بعض الرجال هذا لا ينبغي أن يعتقد أنه جائز، ولو فعله الناس من إبداء الفخذ أو ما تحت السرة، كل هذا وإن فعله بعض الناس في أي حال؛ سواء كان ذلك في لعب الكرة أو في غير ذلك، فإنه يعتبر ممنوعًا ويعتبر خطأ، ولا يجوز إبداء الفخذين لا في حال مسابقة الكرة ولا في غير ذلك، ولا في المجالس إذا جلس الناس فيما بينهم، بل يجب على الرجل أن يفعل ما شرع الله له، وأن يتأدب بالآداب الشرعية فيستر ما بين السرة والركبة، وقد أمر النبي ﷺ بحفظ العورات. فالواجب على المؤمن أن يحفظ عورته، وهكذا المؤمنة عليها أن تحفظ عورتها، وهي كلها عورة عند الرجال، والرجل عورة ما بين السرة والركبة مطلقًا، وفي الصلاة عليه أن يستر عاتقيه أو أحدهما بالرداء أو بأطراف الإزار، هكذا جاءت السنة عن رسول الله عليه الصلاة والسلام، والله المستعان. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17400/حدود-عورة-الرجل-في-الصلاة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86101.mp3","categories":["ستر العورة للمصلي"]},{"id":18741,"question":"ماذا عن كشف باطن القدم عند المرأة أثناء الصلاة؟","title":"حكم ظهور باطن قدم المرأة أثناء الصلاة","answer":"الجواب: إذا كان ثوبها ساترًا، يستر أقدامها في قيامها وركوعها وسجودها، فظهور بطن القدم لا يضر في ظاهر السنة، ولا يبطل صلاتها؛ لأن في حديث أم سلمة لما سئلت....، عن ذلك \"قيل لها: يا أم المؤمنين أتصلي المرأة في درعٍ وخمار؟ فقالت -رضي الله عنها-: إذا كان الدرع سابغًا يغطي ظهور قدميها\".  وقد روي مرفوعًا عن النبي ﷺ ولكن الراجح عند الأئمة وقفه على أم سلمة -رضي الله عنها- فظاهره أن البطون لا يجب سترها، عند السجود مثلًا، والغالب أنها تستتر؛ لأن ثيابها الساترة إذا سجدت تكون وراءها ساترة، لكن لو فرض أن شيئًا من بطن القدم ظهر في بعض الأحيان عند ركوعها أو كذا، لا يضر ذلك؛ لقول أم سلمة: \"إذا كان الدرع سابغًا يغطي ظهور قدميها\" فإذا كان ملابسها سابغة؛ كفى ذلك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17875/حكم-ظهور-باطن-قدم-المراة-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87505.mp3","categories":["ستر العورة للمصلي"]},{"id":18792,"question":"تسأل أختنا وتقول: إذا لم ترتد المرأة الخمار، هل تكون آثمة؟","title":"حكم المرأة إذا لم تلبس الحجاب","answer":"الجواب: نعم، لا بد من ستره ......، أما في الصلاة فلا بأس أن تكشف وجهها في الصلاة إذا كان ما عندها أجنبي، فإن السنة أن تصلي مكشوفة الوجه. أما القدمان فيستران في الصلاة، وهكذا الكفان إذا سترتهما يكون أفضل وإن كشفتهما في الصلاة فالصواب أنه لا حرج في ذلك، ولكن الستر أفضل.  وأما الوجه فالسنة كشفه في الصلاة، وأما إذا كان عندها أجنبي فإنها تستر الجميع في الصلاة وخارجها، نعم.","link":"https://binbaz.org.sa/fatwas/17914/حكم-المراة-اذا-لم-تلبس-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90607.mp3","categories":["اللباس والزينة","ستر العورة للمصلي","قضايا المرأة"]},{"id":19037,"question":"من أسئلة السائلة من اليمن تقول يا سماحة الشيخ: عندما أصلي لا أغطي أطراف أقدامي فما الحكم في ذلك هل صلاتي صحيحة؟","title":"حكم تغطية القدمين للمرأة في الصلاة","answer":"الجواب: الواجب تغطية الأقدام الذي عليه أكثر أهل العلم وجوب تغطية الأقدام، فعليك أن تغطي والماضي نسأل الله أن يعفو عنك، لكن في المستقبل عليك أن تغطي أقدامك بالشراريب بالجوارب أو بالثوب الطويل حتى يتغطى الأقدام كما في حديث أم سلمة لما سئلت وروي مرفوعًا \"هل تصلي المرأة في درع وخمار؟ قالت: إذا كان الدرع سابغًا يغطي ظهور قدميها\". نعم.","link":"https://binbaz.org.sa/fatwas/18204/حكم-تغطية-القدمين-للمراة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88305.mp3","categories":["ستر العورة للمصلي"]},{"id":19352,"question":"ما هي عورة المرأة المسلمة بالنسبة لمحارمها؟ وبالنسبة أيضًا لأخواتها المسلمات؟ ثم لغير المسلمات؟","title":"حد عورة المرأة مع محارمها ومع سائر النساء","answer":"الجواب: أما بالنسبة إلى النساء: فما بين السرة والركبة هذا فيما بين النساء، ولكن ينبغي لها أن تكون محتشمة دائمًا، متسترة دائمًا حتى لا تعتاد التساهل في الأمور. وهكذا مع محارمها تكون متسترة محتشمة إلا في وجهها، ويديها، وقدميها، ولا مانع أن يرى محرمها رأسها لا بأس، لكن كونها تحتشم، وتبتعد عن أسباب الفتنة فلا يرى إلا الوجه، والكفين، أو القدمين عند الحاجة فهذا هو الذي ينبغي، وأن تكون بمنأى عن التساهل ولاسيما في هذا العصر الذي ضعف فيه دين أكثر الخلق، وغلب فيه التساهل من النساء، والتبرج. فينبغي للمؤمنة أن تحرص على أن لا يرى محارمها إلا الشيء الظاهر الغالب كالوجه، والكفين، وإن رأى المحرم كأخيها وعمها رأسها فلا حرج إن شاء الله، لكن التستر في رأسها، وجميع بدنها؛ يكون أولى وأحوط ما عدا الوجه، والكفين، والقدمين حتى تكون بعيدة عن الفتنة، ولاسيما بعض المحارم لا يؤمنون عندهم من الفسق، والتساهل، وقلة الدين ما هو معلوم، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18553/حد-عورة-المراة-مع-محارمها-ومع-ساىر-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94111.mp3","categories":["ستر العورة للمصلي"]},{"id":19388,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: أم سعد رشيدي من الرياض، تسأل جمعًا من الأسئلة في أحدها تقول: ما حكم إظهار اليدين والقدمين في الصلاة، وإن كان لا يجوز فهل إظهارهما يبطل الصلاة، بمعنى أن صلاة المرأة على تلكم الصورة غير صحيحة؟ جزاكم الله خيرًا.","title":"حكم إظهار المرأة لليدين والقدمين في الصلاة","answer":"الجواب: إظهار القدمين في الصلاة لا يجوز عند جمهور أهل العلم، وتبطل الصلاة؛ فإذا صلت وقدماها مشكوفتان وجب عليها أن تعيد عند أكثر العلماء. أما الكفان فأمرهما أوسع إن سترتهما فهو أفضل، وإن أظهرتهما فلا حرج إن شاء الله، نعم، كالوجه، الوجه السنة كشفه إلا أن يكون عندها غير محرم أجنبي تستتر، فإنها تستر وجهها وكفيها، أما إذا كان ما عندها أحد أو ما عندها إلا نساء أو محارم؛ فلا مانع من كشف الكفين، وإن سترتهما فهو أفضل، أما الوجه فالسنة كشفه في الصلاة إذا لم يكن عندها أجنبي.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18609/حكم-اظهار-المراة-لليدين-والقدمين-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_740/nour_74003.mp3","categories":["ستر العورة للمصلي"]},{"id":19398,"question":"تسأل أختنا وتقول: ما حكم ظهور شعر المرأة أو ذراعها أو قدمها في أثناء الصلاة، بدون قصد منها؟","title":"حكم تغطية المرأة كفيها وقدميها وشعرها في الصلاة","answer":"الجواب: الواجب على المرأة التستر في الصلاة، تستر شعرها وبدنها كله وذراعها وقدمها في الصلاة، أما الوجه فيكشف في الصلاة إلا إذا كان عندها أجنبي ليس محرمًا لها تغطي وجهها ولو في الصلاة. أما الكفان فاختلف العلماء فيهما، والأفضل سترهما فإن ظهرا فلا حرج في ذلك على الصحيح إن شاء الله، وإذا ظهر شيء من هذا بغير قصد وهو شيء يسير وسترته في الحال لم يضرها ذلك، إذا انتبهت له وسترته، نعم. المقدم: إذا كانت في بيتها تصلي في غرفتها وغرفتها مغلقة، وليس بها أحد شيخ عبد العزيز ؟\nالشيخ: ولو لابد من سترها.\nالمقدم: لابد من .......\nالشيخ: شعرها وبدنها كله ما عدا الوجه والكفين، نعم.\nالمقدم: جزاكم الله خيرًا، هل يشترط أن يكون هناك غطاء جديد غير الملابس المعتادة شيخ عبد العزيز ؟\nالشيخ: ما يشترط لا يشترط إذا كان عليها ملابس العادة قميصها وخمارها وقميصها الساتر أو عليها مثلًا جوارب كفى ذلك، وإن لبست زيادة جلباب فوق ذلك فهذا خير إلى خير.\nالمقدم: أرى كثير من النساء يحرصن على هذا الجلباب وإن كان لباسها فضفاضًا.\nالشيخ: ما هو ملازم.\nالمقدم: ليس بلازم.\nالشيخ: ما هو بلازم، لا.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18624/حكم-تغطية-المراة-كفيها-وقدميها-وشعرها-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93506.mp3","categories":["ستر العورة للمصلي"]},{"id":19402,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من الرياض حي الملز، وهي من الأخت المستمعة (ب. ع. ح) أختنا تقول: ما هي عورة المرأة للمرأة، مع العلم أن الأخوات المسلمات في الوقت الحاضر أصبحن يظهرن أجزاء كبيرة من ظهورهن ومن بداية أقدامهن حتى الركبة لا لحاجة ولا لضرورة إلا تلبية لموضة أصدرتها نساء الغرب والكافرات وتشبهًا بهن وأصبحت عادة، نرجو من سماحة الشيخ التوجيه، جزاكم الله خيرًا.","title":"عورة المرأة مع المرأة","answer":"الجواب: عورة المرأة للمرأة ما بين السرة والركبة كالرجل مع الرجل، لكن ينبغي للمرأة أن تعتاد الستر وأن تحرص على ستر بدنها عند نسائها وعند غيرهن من أهل بيتها، ينبغي أن تعتاد ذلك لئلا يفشو بينهن التساهل في هذا الأمر. فينبغي للمرأة أن تعتاد ستر بدنها ستر صدرها وظهرها وسيقانها لئلا يراها من لا يبالي بالتهجم على النساء من هنا ومن هنا من خادم وسائق وزوج أخت وأخي زوج ونحو ذلك، تكون متسترة، حتى لو هجم أحد من هؤلاء دخل عليهم بغير إذن أو وهن غافلات فإذا هن متسترات، ولأنها إذا اعتادت التكشف عند النساء قد تعتاده في بيتها عند سائق وعند خادم وعند أخي زوج ونحو ذلك. فالحيطة والذي ينبغي للمرأة أن تكون في غاية من العناية بالستر والحشمة في جميع أحوالها، لكن لو رأت المرأة من المرأة ساقًا أو ظهرًا أو ثديًا أو نحوه لا يضرها ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18628/عورة-المراة-مع-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93509.mp3","categories":["ستر العورة للمصلي"]},{"id":19462,"question":"تقول السائلة يا سماحة الشيخ: هل أستطيع أن أصلي دون أن ألبس ثوبًا خاصًا للصلاة؟","title":"حكم صلاة المرأة في ملابس غير خاصة بالصلاة","answer":"الجواب: نعم، في ملابسها العادية إذا سترت قدميها، أما الوجه مكشوف، إذا كان ما عندها أجنبي السنة كشف الوجه، أما الكفان فالأفضل سترهما، وإن لم تسترهما فلا حرج.","link":"https://binbaz.org.sa/fatwas/18707/حكم-صلاة-المراة-في-ملابس-غير-خاصة-بالصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93904.mp3","categories":["ستر العورة للمصلي"]},{"id":19487,"question":"والدي كبير في السن، ولا يستطيع الحركة، ويحتاج لمن يرعاه، ويعتني به، وأيضًا يحتاج لمن يغير له ملابسه الداخلية، والخارجية؛ فهل علينا إثم في ذلك، وكيف توجهوننا؟ جزاكم الله خيرًا.","title":"حكم انكشاف عورة كبير السن لمحارمه عند خدمته","answer":"الجواب: لا حرج في ذلك الواجب عليكن خدمته إذا كان لا يستطيع أن يخدم نفسه، فالواجب عليكن خدمته، أو على إحداكن خدمته فيما يحتاج إليه، وإن تيسر خادم يقوم بذلك من الرجال، واستطعتم أن توجدوه بالأجرة المناسبة فهذا يكون فيه خير كثير؛ لأن الرجل أقدر على هذه الأمور، وأبعد عن الفتنة، ولكن إذا لم يتيسر ذلك فإنها تخدمه ابنته، أو أخته، أو غيرهما من محارمه، إلا أن تكون له زوجة فإنها هي التي تولى ذلك منه حتى ييسر الله له العافية والشفاء، أو من يخدمه إن عجزت عن ذلك من الرجال الذين يستطيعون هذه الخدمة، إذا عجزت زوجته عن ذلك، أو لم يتيسر من يخدمه غير زوجته. فالحاصل أن بنته، وأخته؛ لا حرج عليها، وهكذا غيرهما من محارمه عند الحاجة إلى خدمته وعدم تيسر زوجة تخدمه. المقدم: جزاكم الله خيرًا، الله المستعان.","link":"https://binbaz.org.sa/fatwas/18734/حكم-انكشاف-عورة-كبير-السن-لمحارمه-عند-خدمته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94506.mp3","categories":["ستر العورة للمصلي"]},{"id":19596,"question":"تقول السائلة: ما حكم الصلاة في ملابس تكون ضيقة ومفتوحة لكن هذه الأخت المصلية تضع عليها غطاء كبير ومتين؟","title":"حكم صلاة المرأة في ثياب ضيقة ومفتوحة مع وضع غطاء فوقها","answer":"الجواب: إذا كانت تسدل نفسها بغطاء كفى، ولكن الأفضل أن تكون الملابس وسطًا، لا ضيقة ولا واسعة كثيرًا، تكون وسطًا هذا هو السنة، وإذا جعلت عليها لحاف يغطي بدنها كله كفى. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18863/حكم-صلاة-المراة-في-ثياب-ضيقة-ومفتوحة-مع-وضع-غطاء-فوقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94802.mp3","categories":["ستر العورة للمصلي"]},{"id":19616,"question":"يقول هذا السائل يا سماحة الشيخ: ما هو حكم الصلاة والرجل حاسر الرأس؟ وهل تغطية الرأس واجبة في كل الأوقات؟","title":"حكم الصلاة الرجل حاسر الرأس","answer":"الجواب: إذا غطى رأسه فهو أفضل، وإن كشف رأسه ورأى أن ذلك أنشط له في صلاته فلا حرج في ذلك، كما يصلي المحرم وهو مكشوف الرأس.","link":"https://binbaz.org.sa/fatwas/18876/حكم-الصلاة-الرجل-حاسر-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94918.mp3","categories":["ستر العورة للمصلي"]},{"id":19726,"question":"يقول هذا السائل: كيف يكون لباس الرجل في الصلاة يا سماحة الشّيخ ؟الشّيخ: كيف؟المقدم: يقول: كيف يكون لباس الرجل في الصلاة؟","title":"كيف يكون لباس الرجل في الصلاة؟","answer":"الجواب: اللباس المعتاد: قميص، أو إزار ورداء، كله كافي، يستر عورته ما بين السرة إلى الركبة، عورة الرجل، ويكون على كتفيه رداء لقوله ﷺ: لا يصلين أحدكم في الثوب الواحد ليس على عاتقه منه شيء فإذا جعل رداء على عاتقيه وصلى في الإزار أو في السراويل كفى صحت صلاته، وإذا لبس ما هو أجمل، كالقميص الزيادة كان أكمل وأفضل، وهكذا لبس العمامة؛ لأن الله يقول: يَا بَنِي آدَمَ خُذُواْ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ[الأعراف: 31]، يعني: عند كل صلاة، فإذا لبس غترته يعني عمامته وقميصًا وصلى في ذلك فهذا حسن، ويكفي في ذلك الإزار والرداء، أو القميص، يكفي، ولو كان مكشوف الرأس. المقدم: جزاكم الله خير يا شيخ عبد العزيز قد يقصد هذا السائل لبس البنطلونات بالنسبة للعمال في المساجد أيضًا؟ الشيخ: لا بد أن يكون اللباس ساترًا، فالعورة ما بين السرة والركبة، والبنطلون إذا كان ما فيه تشبه بالكفرة إذا كان من لباس المسلمين وستر ما بين السرة والركبة أجزأ مع ستر المنكبين أو أحدهما بالرداء.  المقدم: جزاكم الله خيرًا","link":"https://binbaz.org.sa/fatwas/29228/كيف-يكون-لباس-الرجل-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/%D9%83%D9%8A%D9%81%20%D9%8A%D9%83%D9%88%D9%86%20%D9%84%D8%A8%D8%A7%D8%B3%20%D8%A7%D9%84%D8%B1%D8%AC%D9%84%20%D9%81%D9%8A%20%D8%A7%D9%84%D8%B5%D9%84%D8%A7%D8%A9%D8%9F.mp3","categories":["ستر العورة للمصلي","اللباس والزينة","قضايا المرأة"]}]
